const app=document.querySelector('#app');
window.addEventListener('error',e=>{try{const el=document.querySelector('#app');if(el&&!el.innerHTML.trim())el.innerHTML='<div style=\"margin:40px auto;max-width:760px;padding:24px;font-family:system-ui;background:#fff;border:1px solid #fca5a5;border-radius:12px\"><h2>Construction Control could not start</h2><p>The browser loaded the application but a client-side error stopped it.</p><pre style=\"white-space:pre-wrap\">'+String(e.error?.stack||e.message||e).replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]))+'</pre><p>Refresh the page. If the problem remains, send this error to support.</p></div>';}catch(_){} });
window.addEventListener('unhandledrejection',e=>{console.error('Construction Control client error',e.reason)});

let state={me:null,company:null,projects:[],users:[],roles:[],levels:[],audit:[],notifications:[],ent:null,records:[],module:null,projectId:null,settings:null};
const ROLE_VALUES=['Construction Manager','Foreman','Charge Hand','Electrician','4th Year','3rd Year','2nd Year','1st Year','GO'];
const STAFF_LEVELS=['Site Management','Charge Hand','Engineers','Electrician','4th Year','3rd Year','2nd Year','1st Year','General Operative','Subcontractor','Unspecified'];
const STAFF_LEVEL_COLORS={'Site Management':'#ffbd0a','Charge Hand':'#5b8f3b','Engineers':'#f6d1ab','Electrician':'#ff0000','4th Year':'#ff00d8','3rd Year':'#ffff00','2nd Year':'#00ff00','1st Year':'#10a7df','General Operative':'#c0c0c0','Subcontractor':'#9b00ff','Unspecified':'#ffffff'};
async function api(p,o={}){let r=await fetch(p,{headers:{'Content-Type':'application/json',...(o.headers||{})},...o}),d=await r.json().catch(()=>({error:'Invalid server response'}));if(!r.ok)throw Error(d.error||'Request failed');return d}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function login(msg=''){app.innerHTML=`<div class="shell login"><div class="card"><h1>Construction Control</h1><p class="muted">Project Management & Control</p><label>Email</label><input id="email" value="owner@demo.local" autocomplete="username"><label>Password</label><input id="password" type="password" value="DemoPass!123" autocomplete="current-password"><button onclick="go()">Sign in</button><p class="error">${esc(msg)}</p><small>Demo: owner@demo.local / DemoPass!123</small></div></div>`}
async function go(){try{await api('/api/login',{method:'POST',body:JSON.stringify({email:email.value,password:password.value})});await load();render()}catch(e){login(e.message)}}
async function load(){let m=await api('/api/me');let [p,e]=await Promise.all([api('/api/projects'),api('/api/entitlements')]);state={...state,me:m.user,company:m.company,projects:p.projects,ent:e}; let n=await api('/api/notifications'); state.notifications=n.notifications;const accessAdmin=['Company Administrator','Company Director','Business Unit Lead','Construction Manager'].includes(state.me.role); if(accessAdmin){let [u,r]=await Promise.all([api('/api/users'),api('/api/roles')]);state={...state,users:u.users,roles:r.roles,ladder:r.ladder||[]}; if(state.me.role==='Company Administrator'){let [l,a,s]=await Promise.all([api('/api/org'),api('/api/audit'),api('/api/settings')]);state={...state,levels:l.levels,audit:a.audit,settings:s.settings};applySettings()}}else{state={...state,users:[],roles:[],levels:[],audit:[]}}}
function nav(active){const logo=state.company&&state.company.logo_url?`<img class="brand-logo-img" src="${esc(state.company.logo_url)}" alt="Company logo">`:`<div class="brand-logo-placeholder">LOGO</div>`;return `<aside><div class="brand-block">${logo}<div class="brand-name">${esc(state.company?.name||'Construction Control')}</div><div class="brand-product">Construction Control</div></div><button class="nav ${active==='home'?'on':''}" onclick="page('home')">Dashboard</button><button class="nav ${active==='control'?'on':''}" onclick="page('control')">Project Control</button><button class="nav ${active==='management'?'on':''}" onclick="page('management')">Management Centre</button><button class="nav ${active==='planning'?'on':''}" onclick="page('planning')">Programme</button><button class="nav ${active==='daily'?'on':''}" onclick="page('daily')">Morning Brief</button><button class="nav ${active==='closeout'?'on':''}" onclick="page('closeout')">Close Out</button><button class="nav ${active==='staff'?'on':''}" onclick="page('staff')">Staff & Assignments</button><button class="nav" onclick="page('projects')">Projects</button>${['Company Administrator','Company Director','Business Unit Lead','Construction Manager'].includes(state.me.role)?`<button class="nav" onclick="page('users')">Users</button>`:''}${state.me.role==='Company Administrator'?`<button class="nav ${active==='org'?'on':''}" onclick="page('org')">Organisation</button><button class="nav ${active==='roles'?'on':''}" onclick="page('roles')">Access Ladder</button><button class="nav" onclick="page('audit')">Audit trail</button><button class="nav ${active==='settings'?'on':''}" onclick="page('settings')">Settings</button>`:''}<button class="nav nav-logout" onclick="out()">Log out</button></aside>`}
function showProjectHealth(projectId){
 const p=(dashboardData?.project_summary||[]).find(x=>x.project_id===projectId); if(!p)return;
 const colour=p.health==='red'?'red':p.health==='amber'?'amber':'green';
 const title=p.health==='red'?'RED — action required':p.health==='amber'?'AMBER — attention required':'GREEN — currently controlled';
 const reason=p.health_reason||'No current exception recorded.';
 const bullets=[];
 if(p.programme?.overdue)bullets.push(`${p.programme.overdue} overdue programme activit${p.programme.overdue===1?'y':'ies'}`);
 if(p.programme?.held_up)bullets.push(`${p.programme.held_up} held-up activit${p.programme.held_up===1?'y':'ies'}`);
 if((p.today?.planned_men||0)>(p.today?.actual_men||0))bullets.push(`Manpower ${Number(p.today.actual_men).toFixed(1)} actual vs ${Number(p.today.planned_men).toFixed(1)} planned today`);
 if((p.kpis?.external_approvals||0))bullets.push(`${p.kpis.external_approvals} external approval${p.kpis.external_approvals===1?'':'s'} waiting`);
 modal(`${esc(p.project_name)} — ${title}`,`<div class="rag-summary ${colour}"><div class="rag-big">${p.health.toUpperCase()}</div><div><b>${esc(reason)}</b><p class="muted">Based on live programme, manpower and external-approval records.</p></div></div>${bullets.length?`<div class="card"><b>Current indicators</b>${bullets.map(x=>`<div class="mini-row">• ${esc(x)}</div>`).join('')}</div>`:''}<div class="modal-actions"><button onclick="closeModal();state.projectId='${esc(projectId)}';page('daily')">Open today's control</button><button class="secondary" onclick="closeModal();openExternalApprovals('${esc(projectId)}')">External approvals</button></div>`);
}

function pmDailyBrief(projects){
 const late=projects.flatMap(p=>(p.today?.tasks_late||[]).map(t=>({...t,project_name:p.project_name})));
 const starting=projects.flatMap(p=>(p.today?.tasks_starting||[]).map(t=>({...t,project_name:p.project_name})));
 const waiting=projects.reduce((n,p)=>n+Number(p.kpis?.external_approvals||0),0);
 const mp=projects.filter(p=>Number(p.today?.actual_men||0)<Number(p.today?.planned_men||0));
 const chase=[...late.slice(0,2).map(x=>`Chase: ${x.name} — ${x.project_name}`),...projects.filter(p=>Number(p.kpis?.external_approvals||0)>0).slice(0,2).map(p=>`Chase external approval — ${p.project_name}`),...mp.slice(0,2).map(p=>`Check manpower — ${p.project_name}`)];
 return `<section class="pm-brief"><div class="pm-brief-head"><div><span class="eyebrow">PROJECT MANAGER DAILY BRIEF</span><h2>What needs your attention today</h2><p>Simple actions first. Detailed records stay behind the buttons.</p></div><button onclick="page('daily')">✓ Start today's control</button></div><div class="pm-brief-grid"><button onclick="document.querySelector('.late-card')?.scrollIntoView({behavior:'smooth'})"><b>${late.length}</b><span>Needs chasing</span><small>Late starts / overdue work</small></button><button onclick="openExternalApprovals('all')"><b>${waiting}</b><span>External approvals</span><small>Waiting for client / external response</small></button><button onclick="page('daily')"><b>${mp.length}</b><span>Manpower checks</span><small>Below today's plan</small></button><button onclick="document.querySelector('.today-card')?.scrollIntoView({behavior:'smooth'})"><b>${starting.length}</b><span>Starting today</span><small>Planned programme activity</small></button></div>${chase.length?`<div class="pm-chase"><b>Today's chase list</b>${chase.slice(0,5).map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:`<div class="pm-clear">✓ No immediate chase items identified from the current records.</div>`}</section>`;
}

function externalApprovalForm(projectId, existing=null){
 const x=existing||{};
 modal(existing?'Edit external approval':'Add external approval',`<label>Project</label><select id=ea_project>${state.projects.map(p=>`<option value="${esc(p.id)}" ${p.id===(projectId==='all'?state.projectId:projectId)?'selected':''}>${esc(p.name)}</option>`).join('')}</select><label>Approval / item</label><input id=ea_title value="${esc(x.title||'')}" placeholder="e.g. Client approval — RFI-023"><label>Type</label><select id=ea_type>${['Client Approval','Design Approval','Material Approval','Method / RAMS Approval','Programme Approval','Other'].map(v=>`<option ${v===(x.approval_type||'Client Approval')?'selected':''}>${v}</option>`).join('')}</select><label>External party</label><input id=ea_party value="${esc(x.external_party||'')}" placeholder="Client / consultant / external party"><label>Description</label><textarea id=ea_desc rows=3>${esc(x.description||'')}</textarea><label>Requested date</label><input id=ea_req type=date value="${esc(x.requested_date||new Date().toISOString().slice(0,10))}"><label>Required by</label><input id=ea_due type=date value="${esc(x.due_date||'')}">${existing?`<label>Status</label><select id=ea_status>${['Waiting','Approved','Rejected','Cancelled'].map(v=>`<option ${v===x.status?'selected':''}>${v}</option>`).join('')}</select><label>Response date</label><input id=ea_response_date type=date value="${esc(x.response_date||'')}"><label>Response / decision note</label><textarea id=ea_response_note rows=3>${esc(x.response_note||'')}</textarea>`:''}<button onclick="${existing?`saveExternalApproval('${esc(x.id)}')`:'saveExternalApproval()'}">${existing?'Save status':'Add to approval watch list'}</button>`);
}
async function openExternalApprovals(projectId){
 const ids=projectId==='all'?state.projects.map(p=>p.id):[projectId]; let rows=[];
 for(const pid of ids){try{const d=await api('/api/external-approvals?project_id='+encodeURIComponent(pid));(d.approvals||[]).forEach(x=>rows.push({...x,project_name:(state.projects.find(p=>p.id===pid)||{}).name||pid}))}catch(e){}}
 const body=`<div class="bar"><div><b>External approval watch list</b><div class="muted">Waiting for an outside/client response. Your team changes the status when the response arrives.</div></div><button onclick="closeModal();externalApprovalForm('${esc(projectId)}')">+ Add approval</button></div>${rows.length?rows.map(x=>`<div class="row external-approval-row"><div><b>${esc(x.title)}</b><div class="muted">${esc(x.project_name)} • ${esc(x.external_party||'External party')} • due ${esc(x.due_date||'not set')}</div><div>${esc(x.status)}${x.response_note?' • '+esc(x.response_note):''}</div></div><div class="row-actions"><button class="secondary" onclick="externalApprovalForm('${esc(x.project_id)}',${JSON.stringify(x).replace(/</g,'\u003c')})">Edit</button>${x.status==='Waiting'?`<button onclick="externalApprovalForm('${esc(x.project_id)}',${JSON.stringify(x).replace(/</g,'\u003c')})">Update</button>`:''}</div></div>`).join(''):'<p class="muted">No external approvals recorded.</p>'}`;
 modal('External Approvals',body);
}
async function saveExternalApproval(id=null){try{const payload={project_id:ea_project.value,title:ea_title.value,approval_type:ea_type.value,external_party:ea_party.value,description:ea_desc.value,requested_date:ea_req.value,due_date:ea_due.value};if(id){payload.status=ea_status.value;payload.response_date=ea_response_date.value;payload.response_note=ea_response_note.value;await api('/api/external-approvals/'+encodeURIComponent(id),{method:'PUT',body:JSON.stringify(payload)})}else{await api('/api/external-approvals',{method:'POST',body:JSON.stringify(payload)})}closeModal();await home();}catch(e){alert(e.message)}}

function formatDashboardDate(iso){try{return new Intl.DateTimeFormat(undefined,{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date(iso+'T12:00:00'))}catch{return iso}}
function dashboardAttentionCards(projects){
 const late=projects.flatMap(p=>(p.today?.tasks_late||[]).map(t=>({...t,project_id:p.project_id,project_name:p.project_name}))); 
 const starting=projects.flatMap(p=>(p.today?.tasks_starting||[]).map(t=>({...t,project_id:p.project_id,project_name:p.project_name})));
 const mp=projects.filter(p=>Number(p.today?.actual_men||0)<Number(p.today?.planned_men||0));
 const unsaved=projects.filter(p=>!p.today?.daily_saved);
 return {late,starting,mp,unsaved};
}
async function openDashboardTask(projectId,planId,taskId){
 state.projectId=projectId;
 try{
  const d=await api('/api/plans/'+encodeURIComponent(planId));
  const t=(d.tasks||[]).find(x=>x.id===taskId);
  if(!t){throw Error('Task could not be found.');}
  modal('Task — '+esc(t.name),`<div class="task-detail-grid"><div><span class="eyebrow">STATUS</span><b>${esc(t.control_status||t.task_status||t.status||((Number(t.percent_complete||0)>=100)?'Finished':Number(t.percent_complete||0)>0?'Ongoing':'Starting'))}</b></div><div><span class="eyebrow">PROGRESS</span><b>${Number(t.percent_complete||0)}%</b></div><div><span class="eyebrow">DATES</span><b>${esc(t.start_date)} → ${esc(t.finish_date)}</b></div><div><span class="eyebrow">PLANNED MEN</span><b>${Number(t.planned_men||0).toFixed(1)}</b></div></div><p class="muted">Programme: ${esc(d.plan.name)}${t.notes?'<br>'+esc(t.notes):''}</p><div class="modal-actions"><button class="secondary" onclick="closeModal();planning();setTimeout(()=>openPlan('${esc(planId)}'),150)">Open programme</button><button onclick="closeModal();editTask('${esc(planId)}','${esc(taskId)}')">Edit task</button></div>`);
 }catch(e){alert(e.message)}
}
function renderDashboard(){
 const d=dashboardData; const sel=document.getElementById('dashProject')?.value||'all';
 const projects=sel==='all'?d.project_summary:d.project_summary.filter(p=>p.project_id===sel);
 const k=sel==='all'?(d.total_kpis||{}):((projects[0]||{}).kpis||{});
 const att=dashboardAttentionCards(projects);
 const unsaved=att.unsaved;
 const projectOptions=d.project_summary.map(p=>`<option value="${esc(p.project_id)}">${esc(p.project_name)}</option>`).join('');
 const openControls=Number(k.rfis||0)+Number(k.risks||0)+Number(k.actions||0)+Number(k.snags||0);
 const totalLate=att.late.length,totalStarting=att.starting.length,totalMp=att.mp.length;
 const totalPlanned=projects.reduce((n,p)=>n+Number(p.today?.planned_men||0),0),totalActual=projects.reduce((n,p)=>n+Number(p.today?.actual_men||0),0);
 const dateLabel=formatDashboardDate(d.date||new Date().toISOString().slice(0,10));
 const issueCards=DASH_MODULES.map(([label,key,cls])=>`<button class="dash-action ${cls}" onclick="openDashboardModule('${esc(label)}','${sel==='all'?'all':esc(sel)}')"><span class="dash-icon"></span><span><b>${Number(k[key]||0)}</b><small>${label}</small></span><span class="dash-arrow">→</span></button>`).join('');
 const lateRows=att.late.slice(0,6).map(t=>`<button class="attention-item danger" onclick="openDashboardTask('${esc(t.project_id)}','${esc(t.plan_id)}','${esc(t.id)}')"><span><b>${esc(t.name)}</b><small>${esc(t.project_name)} • should have started ${esc(t.start_date)}</small></span><strong>NOT STARTED</strong></button>`).join('');
 const startingRows=att.starting.slice(0,6).map(t=>`<button class="attention-item today" onclick="openDashboardTask('${esc(t.project_id)}','${esc(t.plan_id)}','${esc(t.id)}')"><span><b>${esc(t.name)}</b><small>${esc(t.project_name)} • ${Number(t.planned_men).toFixed(1)} planned men</small></span><strong>START TODAY</strong></button>`).join('');
 const mpRows=att.mp.slice(0,6).map(p=>`<button class="attention-item warning" onclick="page('daily');state.projectId='${esc(p.project_id)}';dailySiteControl()"><span><b>${esc(p.project_name)}</b><small>${Number(p.today.planned_men).toFixed(1)} planned • ${Number(p.today.actual_men).toFixed(1)} on site</small></span><strong>${(Number(p.today.actual_men)-Number(p.today.planned_men)).toFixed(1)}</strong></button>`).join('');
 const dailyRows=unsaved.slice(0,6).map(p=>`<button class="attention-item neutral" onclick="page('daily');state.projectId='${esc(p.project_id)}';dailySiteControl()"><span><b>${esc(p.project_name)}</b><small>Daily Site Control has not been saved for ${esc(d.date)}</small></span><strong>OPEN</strong></button>`).join('');
 const body=`
 <div class="dash-hero"><div><span class="eyebrow">PROJECT CONTROL CENTRE</span><h2>${dateLabel}</h2><p>Good ${new Date().getHours()<12?'morning':new Date().getHours()<18?'afternoon':'evening'}, ${esc(state.me.name.split(' ')[0])}. Here's what needs attention today.</p></div><div class="dash-hero-actions"><select id="dashProject" onchange="renderDashboard()"><option value="all">All projects</option>${projectOptions}</select><button onclick="page('daily')">✓ Open Daily Site Control</button></div></div>
 ${pmDailyBrief(projects)}
 <div class="dash-today-strip"><div><span>Planned men today</span><b>${totalPlanned.toFixed(1)}</b><small>from active programme tasks</small></div><div><span>Actual on site</span><b>${totalActual.toFixed(1)}</b><small>recorded attendance</small></div><div class="${totalActual<totalPlanned?'attention':''}"><span>Manpower variance</span><b>${(totalActual-totalPlanned).toFixed(1)}</b><small>actual − planned</small></div><div><span>Tasks starting</span><b>${totalStarting}</b><small>today</small></div><div class="${totalLate?'attention':''}"><span>Late starts</span><b>${totalLate}</b><small>should already have started</small></div></div>
 <div class="dash-priority-grid">
  <section class="priority-card late-card"><div class="priority-head"><div><span class="eyebrow">🚨 IMMEDIATE</span><h2>Tasks that should have started</h2></div><span class="count danger-count">${totalLate}</span></div>${lateRows||'<div class="priority-empty good">✓ No late-start tasks</div>'}</section>
  <section class="priority-card today-card"><div class="priority-head"><div><span class="eyebrow">📅 TODAY</span><h2>Tasks starting today</h2></div><span class="count today-count">${totalStarting}</span></div>${startingRows||'<div class="priority-empty">No tasks starting today</div>'}</section>
  <section class="priority-card manpower-card"><div class="priority-head"><div><span class="eyebrow">👷 MANPOWER</span><h2>Projects below plan</h2></div><span class="count warning-count">${totalMp}</span></div>${mpRows||'<div class="priority-empty good">✓ No projects below planned manpower</div>'}</section>
  <section class="priority-card daily-card-dash"><div class="priority-head"><div><span class="eyebrow">📝 DAILY CONTROL</span><h2>Daily control still to complete</h2></div><span class="count">${unsaved.length}</span></div>${dailyRows||'<div class="priority-empty good">✓ Daily control saved for all visible projects</div>'}</section>
 </div>
 <div class="dash-grid"><section class="dash-main"><div class="section-head"><div><span class="eyebrow">LIVE CONTROLS</span><h2>Project issues</h2></div><span class="muted">Click any tile to open its records</span></div><div class="dash-actions">${issueCards}</div><div class="section-head projects-head"><div><span class="eyebrow">LIVE PROJECTS</span><h2>Project overview</h2></div></div><div class="project-grid">${dashboardProjectCards(projects)}</div></section></div>`;
 layout('Dashboard',body);
}

async function home(){try{dashboardData=await api('/api/dashboard');renderDashboard()}catch(e){alert(e.message)}}
async function openDashboardModule(module,projectId='all'){
 if(module==='Approvals'){openExternalApprovals(projectId);return}
 const projects=projectId==='all'?(dashboardData?.project_summary||[]):(dashboardData?.project_summary||[]).filter(p=>p.project_id===projectId);
 let records=[];
 for(const p of projects){try{const d=await api('/api/module/'+encodeURIComponent(module)+'?project_id='+encodeURIComponent(p.project_id));(d.records||[]).forEach(r=>records.push({...r,project_name:p.project_name,project_id:p.project_id}))}catch{}}
 if(!records.length){alert(`No ${module.toLowerCase()} found.`);return}
 modal(module,`<div class="detail-toolbar"><p class="muted">${records.length} record${records.length===1?'':'s'} • click a record to open it.</p></div>${records.map(r=>`<button class="dash-record" onclick="openDashboardRecord('${esc(r.project_id)}','${esc(module)}','${esc(r.id)}')"><span><b>${esc(r.title)}</b><small>${esc(r.project_name)} • ${esc(r.created_at||'')}</small></span><span>→</span></button>`).join('')}`);
}
async function openDashboardRecord(projectId,module,recordId){
 document.querySelector('.modal')?.remove(); state.projectId=projectId; state.module=module;
 try{const d=await api('/api/module/'+encodeURIComponent(module)+'?project_id='+encodeURIComponent(projectId));state.records=d.records||[];await loadModuleSpec(module);renderModule();setTimeout(()=>viewRecord(recordId),0)}catch(e){alert(e.message)}
}

function viewRecord(id){
 const r=state.records.find(x=>x.id===id); if(!r)return;
 let data={}; try{data=JSON.parse(r.data_json||'{}')}catch{}
 const spec=currentModuleSpec?.fields||[];
 const fields=spec.map(f=>{const v=f.header==='Title'?r.title:data[f.key]; if(v===undefined||v===null||v==='')return ''; return `<div class="detail-field"><span>${esc(f.header)}</span><b>${esc(v)}</b></div>`}).join('');
 modal(esc(state.module)+' record',`<div class="record-detail"><div class="record-title"><span class="eyebrow">${esc(state.module)}</span><h2>${esc(r.title)}</h2><span class="pill">Created ${esc(r.created_at)}</span></div><div class="detail-grid">${fields||'<p class="muted">No additional fields recorded.</p>'}</div><div class="detail-actions"><button class="secondary" onclick="closeModal();editRecord('${esc(id)}')">Edit</button></div></div>`);
}

async function management(){try{let d=await api('/api/management');let t=d.totals;let cards=`<div class=stats><div class=card><span>Projects</span><b>${t.projects}</b></div><div class=card><span>Open approvals</span><b>${t.pending_approvals}</b></div><div class=card><span>Overdue controls</span><b>${t.overdue_items}</b></div><div class=card><span>Programme overdue</span><b>${t.programme_overdue}</b></div><div class=card><span>Actual manpower</span><b>${Number(t.actual_men).toFixed(1)}</b></div><div class=card><span>Man-hours</span><b>${Number(t.man_hours).toFixed(1)}</b></div></div>`;let rows=d.projects.map(p=>`<div class=row><div style="flex:1"><b>${esc(p.project_name)}</b><div class=muted>${p.records} records • ${p.programme?`Programme ${esc(p.programme.name)} • ${p.programme.progress}% • finish ${esc(p.programme.finish||'—')}`:'No programme'}</div><div class=mini-kpis><span>RFIs ${p.open.RFIs||0}</span><span>Risks ${p.open.Risks||0}</span><span>Actions ${p.open.Actions||0}</span><span>Snags ${p.open.Snags||0}</span><span>Approvals ${p.pending_approvals}</span><span>Manpower ${Number(p.manpower.actual_men).toFixed(1)} / ${Number(p.manpower.planned_men).toFixed(1)}</span></div></div><button class=secondary onclick="quickOpenProject('${esc(p.project_id)}')">Open</button></div>`).join('')||'<p class=muted>No accessible projects.</p>';let issues=d.issues.map(x=>`<div class=row><div><b>${esc(x.kind)}</b><div>${esc(x.title)} • ${esc(x.module)} • ${esc(x.project_name)}</div><div class=muted>${x.due_date?'Due '+esc(x.due_date)+' • ':''}${esc(x.status)}</div></div></div>`).join('')||'<p class=muted>No actionable issues found.</p>';let prog=d.programme.map(x=>`<div class=row><div><b>${esc(x.project_name)} — ${esc(x.name)}</b><div class=muted>${x.progress}% • finish ${esc(x.finish||'—')} • baseline ${esc(x.baseline_finish||'—')} • variance ${x.finish_variance_days===null?'—':x.finish_variance_days+'d'} • overdue activities ${x.overdue_activities}</div></div></div>`).join('')||'<p class=muted>No programmes.</p>';layout('Management Control Centre',`${cards}<div class=card><h2>Project control overview</h2>${rows}</div><div class=card><h2>Programme performance</h2>${prog}</div><div class=card><h2>Actionable issues</h2><p class=muted>Items are factual records derived from live project data. Overdue means the stored due/target date is before today and the status is not closed/complete.</p>${issues}</div>`,'management')}catch(e){alert(e.message)}}


const bulkModules=['Daily Control','Manpower','RFIs','Risks','Actions','Snags','Materials','Procurement','RAMS','Permits','Commissioning','Variations','Cost Control','Handover','Reports'];
async function bulkImport(){
 if(!state.projectId){alert('Select a project first');return}
 modal('Bulk Excel Import',`<p class=muted>Choose a module, download its template, complete the Template sheet, delete the example row, save the workbook, then upload it here.</p><label>Module<select id=biModule>${bulkModules.map(m=>`<option>${esc(m)}</option>`).join('')}</select></label><div class=formgrid><button class=secondary onclick="downloadBulkTemplate()">Download Excel Template</button><label>Excel file<input id=biFile type=file accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"></label></div><button onclick="uploadBulkFile()">Validate & Import</button><div id=biResult></div><h4>Recent imports</h4><div id=biHistory><p class=muted>Loading...</p></div>`);
 loadBulkHistory();
}
async function downloadBulkTemplate(){try{let m=biModule.value;let r=await fetch('/api/bulk-import/templates?module='+encodeURIComponent(m));if(!r.ok){let d=await r.json().catch(()=>({}));throw Error(d.error||'Template download failed')}let b=await r.blob();let a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='Construction_Control_'+m.replaceAll(' ','_')+'_Import_Template.xlsx';a.click();URL.revokeObjectURL(a.href)}catch(e){alert(e.message)}}
async function uploadBulkFile(){
 if(!biFile.files[0]){alert('Choose an Excel file');return}
 try{let fd=new FormData();fd.append('file',biFile.files[0]);let r=await fetch('/api/bulk-import?project_id='+encodeURIComponent(state.projectId)+'&module='+encodeURIComponent(biModule.value),{method:'POST',body:fd});let d=await r.json();if(!r.ok)throw Error((d.error||'Import failed')+(d.errors?.length?'\n'+d.errors.slice(0,8).map(x=>'Row '+x.row+': '+x.errors.join(', ')).join('\n'):''));biResult.innerHTML=`<p class=success>Imported ${d.rows_imported} row(s) successfully.</p>`;await loadBulkHistory();await chooseModule(biModule.value)}catch(e){biResult.innerHTML=`<p class=error>${esc(e.message).replace(/\n/g,'<br>')}</p>`}
}
async function loadBulkHistory(){try{let d=await api('/api/bulk-import/history?project_id='+encodeURIComponent(state.projectId));let rows=d.imports.map(x=>`<div class=row><div><b>${esc(x.module)}</b><div class=muted>${esc(x.filename)} • ${x.rows_imported}/${x.rows_read} imported • ${esc(x.created_at)}</div></div></div>`).join('')||'<p class=muted>No imports yet.</p>';let el=document.getElementById('biHistory');if(el)el.innerHTML=rows}catch(e){let el=document.getElementById('biHistory');if(el)el.innerHTML='<p class=error>Could not load import history.</p>'}}

function quickOpenProject(id){state.projectId=id;page('project')}
async function projectOverview(){
 if(!state.projectId){
   layout('Project Overview',`<div class="card"><h2>Select a project</h2><select id="overviewProject" onchange="state.projectId=this.value;projectOverview()"><option value="">Choose a project</option>${state.projects.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></div>`);
   return;
 }
 try{
   const d=await api('/api/project-overview?project_id='+encodeURIComponent(state.projectId));
   const p=d.project, k=d.kpis, prog=d.programme;
   const moduleNames={"Daily Control":"Daily Control","Manpower":"Manpower","RFIs":"RFIs","Risks":"Risks","Actions":"Actions","Snags":"Snags","Materials":"Materials","Procurement":"Procurement","RAMS":"RAMS","Permits":"Permits","Commissioning":"Commissioning","Variations":"Variations","Cost Control":"Cost Control","Handover":"Handover","Reports":"Reports","Documents":"Documents"};
   const moduleTiles=d.modules.map(m=>`<button class="cockpit-module" onclick="openDashboardModule('${esc(m.module)}','${esc(p.id)}')"><span class="cockpit-module-name">${esc(moduleNames[m.module]||m.module)}</span><b>${m.count}</b><span class="muted">Open records</span></button>`).join('');
   const attention=d.attention.map(x=>`<button class="cockpit-attention" onclick="openDashboardRecord('${esc(p.id)}','${esc(x.module)}','${esc(x.id)}')"><span><b>${esc(x.title)}</b><small>${esc(x.module)} • ${esc(x.status)} • Due ${esc(x.due_date)}</small></span><span class="cockpit-badge red">OVERDUE</span></button>`).join('')||'<div class="empty-state">No overdue control items.</div>';
   const recent=d.recent.map(x=>`<button class="cockpit-recent" onclick="openDashboardRecord('${esc(p.id)}','${esc(x.module)}','${esc(x.id)}')"><span><b>${esc(x.title)}</b><small>${esc(x.module)} • ${esc(x.status)}</small></span><span>→</span></button>`).join('')||'<div class="empty-state">No project records yet.</div>';
   const programme=prog?`<div class="cockpit-programme"><div class="cockpit-programme-head"><div><span class="eyebrow">PROGRAMME</span><h3>${esc(prog.name)}</h3><p class="muted">${prog.activities} activities • ${prog.progress}% complete • finish ${esc(prog.finish||'—')}</p></div><button class="secondary" onclick="openPlan('${esc(prog.id)}')">Open programme →</button></div><div class="progress-track"><span style="width:${Math.max(0,Math.min(100,Number(prog.progress)||0))}%"></span></div><div class="cockpit-programme-foot"><span>Baseline ${esc(prog.baseline_finish||'—')}</span><span>Variance ${prog.finish_variance_days===null||prog.finish_variance_days===undefined?'—':prog.finish_variance_days+'d'}</span><span>Overdue activities ${prog.overdue_activities}</span></div></div>`:`<div class="empty-state">No programme has been created for this project. <button onclick="page('planning')">Create programme</button></div>`;
   const body=`<div class="cockpit-head"><div><span class="eyebrow">PROJECT CONTROL ROOM</span><h2>${esc(p.name)}</h2><p class="muted">One live view of programme, manpower, controls, documents and recent activity.</p></div><div class="cockpit-actions"><button class="secondary" onclick="page('control')">Project Control</button><button onclick="page('planning')">Programme</button></div></div>
   <div class="cockpit-strip"><div><span>Records</span><b>${k.records}</b></div><div><span>Actual men</span><b>${Number(k.actual_men).toFixed(1)}</b><small>${Number(k.today_actual_men).toFixed(1)} today</small></div><div><span>Planned men</span><b>${Number(k.planned_men).toFixed(1)}</b><small>${Number(k.today_planned_men).toFixed(1)} today</small></div><div><span>Man-hours</span><b>${Number(k.man_hours).toFixed(1)}</b><small>${Number(k.today_man_hours).toFixed(1)} today</small></div><div><span>Approvals</span><b>${k.pending_approvals}</b><small>pending</small></div><div><span>Documents</span><b>${k.documents}</b><small>uploaded</small></div></div>
   <div class="cockpit-grid"><section><div class="section-head"><div><span class="eyebrow">CONTROLS</span><h2>Project modules</h2></div><span class="muted">Select a tile to open the live records</span></div><div class="cockpit-modules">${moduleTiles}</div>${programme}<div class="section-head cockpit-section"><div><span class="eyebrow">ATTENTION</span><h2>Needs attention</h2></div></div><div>${attention}</div></section><aside class="cockpit-side"><div class="card"><div class="section-head"><div><span class="eyebrow">RECENT</span><h2>Latest project records</h2></div></div>${recent}</div><div class="card cockpit-help"><h3>Quick entry</h3><p class="muted">Add or edit records using the same fields as the Excel import templates.</p><button onclick="page('control')">Open Project Control</button><button class="secondary" onclick="bulkImport()">Bulk Excel Import</button></div></aside></div>`;
   layout('Project Overview',body,'control');
 }catch(e){alert(e.message)}
}

function control(){let mods=state.ent.features.includes('core')?['Daily Control','Manpower','RFIs','Risks','Actions','Snags','Materials','Procurement','RAMS','Permits','Commissioning','Variations','Cost Control','Handover','Reports','Documents','Project Planning']:[];layout('Project Control',`<div class=card><h2>Select project</h2><select id=cp onchange=loadModuleList()><option value="">Choose a project</option>${state.projects.map(p=>`<option value="${esc(p.id)}" ${state.projectId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><button class=secondary onclick=projectOverview()>Open project overview</button><div class=modulegrid>${mods.map(m=>`<button class=secondary onclick=chooseModule('${esc(m)}')>${esc(m)}</button>`).join('')}</div><div class=card style="margin-top:12px"><h3>Bulk Excel Import</h3><p class=muted>Download a controlled Excel template, complete it, then import multiple records into the selected project.</p><button class=secondary onclick=bulkImport()>Open Bulk Import</button></div><div id=moduleArea><p class=muted>Select a project and module.</p></div></div>`,'control')}
function loadModuleList(){state.projectId=cp.value;document.getElementById('moduleArea').innerHTML='<p class=muted>Select a module.</p>'}
async function chooseModule(module){if(!state.projectId){alert('Select a project first');return}if(module==='Documents'){return documents()} if(module==='Project Planning'){return planning()}state.module=module;try{let d=await api('/api/module/'+encodeURIComponent(module)+'?project_id='+encodeURIComponent(state.projectId));state.records=d.records;renderModule()}catch(e){alert(e.message)}}
async function renderModule(){let canCreate=state.me.role==='Company Administrator'; let wf=[]; try{let d=await api('/api/workflows?project_id='+encodeURIComponent(state.projectId)); wf=d.workflows.filter(x=>x.module===state.module)}catch{} let items=state.records.map(r=>{let w=wf.find(x=>x.record_id===r.id&&x.status==='Pending'); let action=w&&state.me.id===w.approver_user_id?`<button class="secondary" onclick="decideWorkflow('${esc(w.id)}','Approved')">Approve</button><button class="secondary" onclick="decideWorkflow('${esc(w.id)}','Rejected')">Reject</button>`:''; return `<div class="row record-row"><button class="record-open" onclick="viewRecord('${esc(r.id)}')"><b>${esc(r.title)}</b><span class="muted">${esc(r.created_at)}${w?' • Approval: '+esc(w.status):''}</span></button><div>${canCreate?`<button class="secondary" onclick="editRecord('${esc(r.id)}')">Edit</button><button class="secondary" onclick="requestApproval('${esc(r.id)}')">Request approval</button>`:''}${action}</div></div>`}).join('')||'<p class=muted>No records yet.</p>';document.getElementById('moduleArea').innerHTML=`<div class="bar"><div><span class="eyebrow">PROJECT CONTROL</span><h2>${esc(state.module)}</h2></div><button onclick=newRecord()>+ Add record</button></div><p class="muted">Click a record to view its details.</p>${items}`}

async function requestApproval(id){let approvers=state.users.filter(u=>u.active&&u.id!==state.me.id); if(!approvers.length){alert('No active approver available');return} modal('Request approval',`<label>Approver</label><select id=ap>${approvers.map(u=>`<option value="${esc(u.id)}">${esc(u.name)} — ${esc(u.role)}</option>`).join('')}</select><button onclick="sendApproval('${esc(id)}')">Send request</button>`)}
async function sendApproval(id){try{await api('/api/workflows',{method:'POST',body:JSON.stringify({project_id:state.projectId,module:state.module,record_id:id,approver_user_id:ap.value})});closeModal();await chooseModule(state.module)}catch(e){alert(e.message)}}
async function decideWorkflow(id,decision){let note=prompt('Optional note:','');try{await api('/api/workflows/'+id,{method:'PUT',body:JSON.stringify({decision,note:note||''})});await load();await chooseModule(state.module)}catch(e){alert(e.message)}}
function notifications(){let items=state.notifications.map(n=>{let btn=n.read_at?'':`<button class=secondary onclick="readNotification('${esc(n.id)}')">Mark read</button>`;return `<div class=row><div><b>${esc(n.title)}</b><div class=muted>${esc(n.message)} • ${esc(n.created_at)}</div></div>${btn}</div>`}).join('')||'<p class=muted>No notifications.</p>';layout('Notifications',`<div class=card><h2>Your notifications</h2>${items}</div>`,'notifications')}
async function readNotification(id){try{await api('/api/notifications/'+id,{method:'PUT',body:'{}'});await load();notifications()}catch(e){alert(e.message)}}
let currentModuleSpec=null;
async function loadModuleSpec(module){
  const d=await api('/api/module-spec?module='+encodeURIComponent(module));
  currentModuleSpec=d;
  return d;
}
function fieldControl(f,value){
  const id='df_'+f.key;
  const val=value==null?'':String(value);
  const req=f.required?' <span class=req>*</span>':'';
  if(f.type==='date') return `<label>${esc(f.header)}${req}</label><input id="${id}" type="date" value="${esc(val.slice(0,10))}">`;
  if(f.type==='number') return `<label>${esc(f.header)}${req}</label><input id="${id}" type="number" step="any" value="${esc(val)}">`;
  if(f.type==='role') return `<label>${esc(f.header)}${req}</label><select id="${id}"><option value="">Select...</option>${(currentModuleSpec.role_values||[]).map(x=>`<option value="${esc(x)}" ${x===val?'selected':''}>${esc(x)}</option>`).join('')}</select>`;
  if(f.header==='Notes') return `<label>${esc(f.header)}${req}</label><textarea id="${id}" rows="4">${esc(val)}</textarea>`;
  return `<label>${esc(f.header)}${req}</label><input id="${id}" value="${esc(val)}">`;
}
function collectRecordData(){
  const data={};
  for(const f of currentModuleSpec.fields){
    if(f.header==='Title') continue;
    const el=document.getElementById('df_'+f.key);
    data[f.key]=el?el.value:'';
  }
  return data;
}
async function newRecord(){
  try{
    await loadModuleSpec(state.module);
    const fields=currentModuleSpec.fields.map(f=>fieldControl(f,'')).join('');
    modal('New '+esc(state.module)+' record',fields+'<button onclick="saveRecord()">Save</button>');
  }catch(e){alert(e.message)}
}
async function saveRecord(){
  try{
    const titleEl=document.getElementById('df_title');
    const title=titleEl?titleEl.value:'';
    const data=collectRecordData();
    await api('/api/module/'+encodeURIComponent(state.module),{method:'POST',body:JSON.stringify({project_id:state.projectId,title,data})});
    closeModal(); await chooseModule(state.module);
  }catch(e){alert(e.message)}
}
async function editRecord(id){
  try{
    const r=state.records.find(x=>x.id===id); let data={};
    try{data=JSON.parse(r.data_json||'{}')}catch{}
    await loadModuleSpec(state.module);
    const fields=currentModuleSpec.fields.map(f=>fieldControl(f,f.header==='Title'?r.title:data[f.key])).join('');
    modal('Edit '+esc(state.module)+' record',fields+`<button onclick="saveRecordEdit('${esc(id)}')">Save</button>`);
  }catch(e){alert(e.message)}
}
async function saveRecordEdit(id){
  try{
    const titleEl=document.getElementById('df_title');
    const title=titleEl?titleEl.value:'';
    const data=collectRecordData();
    await api('/api/module/'+encodeURIComponent(state.module)+'/'+id,{method:'PUT',body:JSON.stringify({title,data})});
    closeModal(); await chooseModule(state.module);
  }catch(e){alert(e.message)}
}

function companyEdit(){modal('Company branding',`<label>Company name</label><input id=cn value="${esc(state.company.name)}"><label>Country</label><input id=cc value="${esc(state.company.country)}"><label>Logo URL</label><input id=cl value="${esc(state.company.logo_url||'')}" placeholder="https://..."><p class=muted>For now use a hosted image URL. A direct logo upload can be added later.</p><button onclick="saveCompany()">Save branding</button>`)}
async function saveCompany(){try{await api('/api/company',{method:'PUT',body:JSON.stringify({name:cn.value,country:cc.value,logo_url:cl.value})});closeModal();await load();home()}catch(e){alert(e.message)}}

async function documents(){if(!state.projectId){alert('Select a project first');return}try{let d=await api('/api/attachments?project_id='+encodeURIComponent(state.projectId));layout('Documents',`<div class=card><div class=bar><h2>Project documents</h2><button onclick="uploadDocument()">+ Upload</button></div>${d.attachments.map(a=>`<div class=row><div><b>${esc(a.filename)}</b><div class=muted>${esc(a.mime_type)} • ${Math.round(a.size_bytes/1024)} KB • ${esc(a.created_at)}</div></div><a class=secondary href="/api/attachments/${esc(a.id)}">Open</a></div>`).join('')||'<p class=muted>No documents yet.</p>'}</div>`,'control')}catch(e){alert(e.message)}}
function uploadDocument(){modal('Upload document',`<label>File</label><input id=df type=file><p class=muted>Development limit: 10 MB.</p><button onclick="saveDocument()">Upload</button>`)}
async function saveDocument(){let f=df.files[0];if(!f){alert('Choose a file');return}if(f.size>10*1024*1024){alert('File is larger than 10 MB');return}let b64=await new Promise((res,rej)=>{let r=new FileReader();r.onload=()=>res(String(r.result).split(',')[1]);r.onerror=rej;r.readAsDataURL(f)});try{await api('/api/attachments',{method:'POST',body:JSON.stringify({project_id:state.projectId,filename:f.name,mime_type:f.type||'application/octet-stream',content_base64:b64})});closeModal();documents()}catch(e){alert(e.message)}}

function projects(){let admin=state.me.role==='Company Administrator';layout('Projects',`<div class="card"><div class="bar"><div><div class="eyebrow">PROJECT REGISTER</div><h2>Project access</h2></div>${admin?'<button onclick="newProject()">+ New project</button>':''}</div>${state.projects.map(p=>`<div class="project-row"><div><div class="project-row-title"><b>${esc(p.name)}</b><span class="status-dot"></span></div><div class="muted">${esc(p.id)}${p.level_name?' • '+esc(p.level_name):''}</div><div class="project-meta">${p.start_date?esc(p.start_date):'Start not set'} ${p.finish_date?'→ '+esc(p.finish_date):''}${p.client_name?' • '+esc(p.client_name):''}</div></div><div class="project-row-actions">${admin?`<button class="secondary" onclick="editProject('${esc(p.id)}')">Edit</button>`:''}<button onclick="state.projectId='${esc(p.id)}';page('control')">Open →</button></div></div>`).join('')||'<p class=muted>No projects</p>'}</div>`)}
function closeModal(){const m=document.querySelector('.modal');if(m)m.remove()}
function modal(title,body){closeModal();let m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modalbox"><div class=bar><h2>${title}</h2><button class=secondary onclick="closeModal()">Close</button></div>${body}</div>`;document.body.appendChild(m)}
async function newProject(){modal('New project',`<label>Name</label><input id=pn><div class=form-grid><div><label>Start date</label><input id=ps type=date></div><div><label>Finish date</label><input id=pf type=date></div></div><label>Client / Employer</label><input id=pc><label>Site address</label><input id=pa><label>Scope reference</label><input id=pscope value="SOW-DC-001 Rev 1.1"><label>Project manloader</label><input id=pm type=number min=0 step=0.5 value=0><label>Organisation level</label><select id=pl><option value="">None</option>${state.levels.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select><button onclick="saveProject()">Create project</button>`)}
async function saveProject(){try{await api('/api/projects',{method:'POST',body:JSON.stringify({name:pn.value,start_date:ps.value,finish_date:pf.value,client_name:pc.value,site_address:pa.value,scope_ref:pscope.value,level_id:pl.value||null,manloader:Number(pm.value||0)})});closeModal();await load();projects()}catch(e){alert(e.message)}}
async function editProject(id){let p=state.projects.find(x=>x.id===id);modal('Edit project',`<label>Name</label><input id=en value="${esc(p.name)}"><div class=form-grid><div><label>Start date</label><input id=es type=date value="${esc(p.start_date||'')}"></div><div><label>Finish date</label><input id=ef type=date value="${esc(p.finish_date||'')}"></div></div><label>Client / Employer</label><input id=ec value="${esc(p.client_name||'')}"><label>Site address</label><input id=ea value="${esc(p.site_address||'')}"><label>Scope reference</label><input id=escope value="${esc(p.scope_ref||'')}"><label>Project manloader</label><input id=em type=number min=0 step=0.5 value="${Number(p.manloader||0)}"><label>Organisation level</label><select id=el><option value="">None</option>${state.levels.map(x=>`<option value="${x.id}" ${x.id===p.level_id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><button onclick="saveProjectEdit('${id}')">Save</button>`)}
async function saveProjectEdit(id){try{await api('/api/projects/'+id,{method:'PUT',body:JSON.stringify({name:en.value,start_date:es.value,finish_date:ef.value,client_name:ec.value,site_address:ea.value,scope_ref:escope.value,level_id:el.value||null,manloader:Number(em.value||0)})});closeModal();await load();projects()}catch(e){alert(e.message)}}
function org(){layout('Organisation & Company',`<div class="card brand-settings-card"><div class="bar"><div><div class="eyebrow">COMPANY BRANDING</div><h2>Company identity</h2><p class="muted">Your logo and company identity appear throughout the application.</p></div><button onclick="companyEdit()">Edit branding</button></div><div class="brand-preview">${state.company.logo_url?`<img src="${esc(state.company.logo_url)}" alt="Company logo">`:'<div class="brand-logo-placeholder large">YOUR LOGO</div>'}<div><b>${esc(state.company.name)}</b><div class="muted">${esc(state.company.country)}</div></div></div></div><div class="card"><div class="bar"><div><div class="eyebrow">ORGANISATION</div><h2>Reporting structure</h2></div><button onclick="newLevel()">+ Add level</button></div>${state.levels.map(x=>`<div class=row><div><b>${esc(x.name)}</b><div class=muted>Parent: ${esc(x.parent_name||'None')}</div></div><button class=secondary onclick="editLevel('${x.id}')">Edit</button></div>`).join('')||'<p class=muted>No levels</p>'}</div>`,'org')}
function newLevel(){modal('Add organisation level',`<label>Name</label><input id=ln><label>Parent</label><select id=lp><option value="">None</option>${state.levels.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select><button onclick="saveLevel()">Create</button>`)}
async function saveLevel(){try{await api('/api/org',{method:'POST',body:JSON.stringify({name:ln.value,parent_id:lp.value||null})});closeModal();await load();org()}catch(e){alert(e.message)}}
function editLevel(id){let x=state.levels.find(v=>v.id===id);modal('Edit organisation level',`<label>Name</label><input id=ln value="${esc(x.name)}"><label>Parent</label><select id=lp><option value="">None</option>${state.levels.filter(v=>v.id!==id).map(v=>`<option value="${v.id}" ${v.id===x.parent_id?'selected':''}>${esc(v.name)}</option>`).join('')}</select><button onclick="updateLevel('${id}')">Save</button>`)}
async function updateLevel(id){try{await api('/api/org/'+id,{method:'PUT',body:JSON.stringify({name:ln.value,parent_id:lp.value||null})});closeModal();await load();org()}catch(e){alert(e.message)}}
function users(){const admin=state.me.role==='Company Administrator';const manageable=admin?state.users:state.users.filter(u=>{const allowed=state.me.role==='Construction Manager'?['Foreman','Charge Hand','Site User','Viewer']:state.me.role==='Business Unit Lead'?['Construction Manager','Foreman','Charge Hand','Site User','Viewer']:state.me.role==='Company Director'?['Business Unit Lead','Construction Manager','Foreman','Charge Hand','Site User','Viewer']:[];return allowed.includes(u.role)});layout('Users',`<div class=card><div class=bar><h2>Company users</h2>${admin?'<button onclick="newUser()">+ Add user</button>':''}</div><p class=muted>${admin?'Add users and manage their roles.':'Assign users to projects you control. Foremen and Charge Hands have site-control access.'}</p>${manageable.map(u=>`<div class=row><div><b>${esc(u.name)}</b><div class=muted>${esc(u.email)} • ${esc(u.role)}</div></div><span class="pill ${u.active?'':'off'}">${u.active?'Active':'Disabled'}</span><button class=secondary onclick="editUser('${u.id}')">${admin?'Edit':'Project access'}</button></div>`).join('')||'<p class=muted>No users at this level are available to manage.</p>'}</div>`,'users')}
function roleOptions(selected){return state.roles.map(r=>`<option value="${r.name}" ${r.name===selected?'selected':''}>${esc(r.name)}</option>`).join('')}
function newUser(){modal('Add user',`<label>Name</label><input id=un><label>Email</label><input id=ue type=email><label>Temporary password</label><input id=up type=password><label>Role</label><select id=ur>${roleOptions('')}</select><label>Active</label><select id=ua><option value="1">Yes</option><option value="0">No</option></select><button onclick="saveUser()">Create user</button>`)}
async function saveUser(){try{await api('/api/users',{method:'POST',body:JSON.stringify({name:un.value,email:ue.value,password:up.value,role:ur.value,active:ua.value==='1'})});closeModal();await load();users()}catch(e){alert(e.message)}}
function editUser(id){let u=state.users.find(x=>x.id===id);if(!u)return;const admin=state.me.role==='Company Administrator';const header=admin?`<label>Name</label><input id=un value="${esc(u.name)}"><label>Role</label><select id=ur>${roleOptions(u.role)}</select><label>Active</label><select id=ua><option value="1" ${u.active?'selected':''}>Yes</option><option value="0" ${!u.active?'selected':''}>No</option></select><button onclick="updateUser('${id}')">Save</button>`:`<p class=muted>${esc(u.name)} • ${esc(u.role)}</p>`;modal('User access',`${header}<hr><h3>Project access</h3>${state.projects.map(p=>`<label class=check><input type=checkbox class=pa value="${p.id}"> ${esc(p.name)}</label>`).join('')}<button onclick="loadAccess('${id}')">Load access</button><button onclick="saveAccess('${id}')">Save project access</button>`)}
async function loadAccess(id){let d=await api('/api/users/'+id+'/access');document.querySelectorAll('.pa').forEach(x=>x.checked=d.project_ids.includes(x.value))}
async function updateUser(id){try{await api('/api/users/'+id,{method:'PUT',body:JSON.stringify({name:un.value,role:ur.value,active:ua.value==='1'})});closeModal();await load();users()}catch(e){alert(e.message)}}
async function saveAccess(id){try{let project_ids=[...document.querySelectorAll('.pa:checked')].map(x=>x.value);await api('/api/users/'+id+'/access',{method:'PUT',body:JSON.stringify({project_ids})});alert('Project access saved');await load()}catch(e){alert(e.message)}}
function roles(){layout('Access Ladder',`<div class="card"><div class="bar"><div><div class="eyebrow">ACCESS CONTROL</div><h2>Roles & permissions</h2><p class="muted">Use the ladder for normal staff access. Fine-grained permissions remain available under Advanced.</p></div><button onclick="newRole()">+ Add role</button></div><div class="access-ladder">${state.roles.map(r=>`<div class="ladder-row"><div class="ladder-level">${Number(r.access_level||1)}</div><div class="ladder-copy"><b>${esc(r.name)}</b><div class="muted">${esc((state.ladder||[]).find(x=>Number(x.level)===Number(r.access_level))?.description||'Custom access level')}${r.parent_name?' • inherits from '+esc(r.parent_name):''}</div></div><span class="pill">Level ${Number(r.access_level||1)}</span><button class="secondary" onclick="editRole('${r.id}')">Edit</button></div>`).join('')}</div></div>`,'roles')}
function newRole(){modal('New access role',`<label>Role name</label><input id=rn placeholder="e.g. Project Coordinator"><label>Access level</label><select id=rl>${(state.ladder||[]).map(x=>`<option value="${x.level}">${x.level} — ${esc(x.name)} — ${esc(x.description)}</option>`).join('')}</select><label>Inherits from</label><select id=rp><option value="">None</option>${state.roles.filter(r=>Number(r.access_level||1)<8).map(r=>`<option value="${r.id}">${esc(r.name)} (Level ${Number(r.access_level||1)})</option>`).join('')}</select><button onclick="saveRole()">Create role</button>`)}
async function saveRole(){try{await api('/api/roles',{method:'POST',body:JSON.stringify({name:rn.value,access_level:Number(rl.value),parent_role_id:rp.value||null})});closeModal();await load();roles()}catch(e){alert(e.message)}}
async function editRole(id){let d=await api('/api/roles/'+id);modal('Access: '+esc(d.role.name),`<div class="access-summary"><div class="access-level-big">Level ${Number(d.role.access_level||1)}</div><div><b>${esc(d.role.name)}</b><div class=muted>${esc((state.ladder||[]).find(x=>Number(x.level)===Number(d.role.access_level||1))?.description||'Custom access level')}</div></div></div><details class=advanced-permissions><summary>Advanced permissions</summary><div class="permgrid">${d.permissions.map(p=>`<label class=check><input type=checkbox data-module="${esc(p.module)}" data-action="${esc(p.action)}" ${p.allowed?'checked':''}> ${esc(p.module)} — ${esc(p.action)}</label>`).join('')}</div><button onclick="saveRolePerms('${id}')">Save advanced permissions</button></details>`)}
async function saveRolePerms(id){let permissions=[...document.querySelectorAll('[data-module]')].map(x=>({module:x.dataset.module,action:x.dataset.action,allowed:x.checked}));try{await api('/api/roles/'+id+'/permissions',{method:'PUT',body:JSON.stringify({permissions})});closeModal();await load();roles()}catch(e){alert(e.message)}}

function applyThemeValues(s){if(!s)return;const r=document.documentElement;r.style.setProperty('--header-color',s.accent_color||'#2563eb');r.style.setProperty('--sidebar',s.sidebar_color||'#0f172a')}
function applySettings(){applyThemeValues(state.settings)}
function previewSettings(){applyThemeValues({accent_color:setHeader.value,sidebar_color:setSidebar.value})}
function settings(){const s=state.settings||{accent_color:'#2563eb',sidebar_color:'#0f172a',dashboard_default:'management'};layout('Settings',`<div class=card><div class=bar><div><span class=eyebrow>COMPANY COLOUR SCHEME</span><h2>Application settings</h2><p class=muted>Choose the colours used for the company header and navigation. Dashboard status colours remain fixed so they continue to communicate project health clearly.</p></div></div><div class=form-grid><label>Header colour<input id=setHeader type=color value="${esc(s.accent_color||'#2563eb')}" oninput="previewSettings()"></label><label>Sidebar colour<input id=setSidebar type=color value="${esc(s.sidebar_color||'#0f172a')}" oninput="previewSettings()"></label></div><div class=bar style="margin-top:14px"><span class=muted>Blue, green, amber, red, purple and teal are reserved for operational/status meaning.</span><button onclick="saveSettings()">Save company colours</button></div></div><div class=card><h2>Company branding</h2><p class=muted>Logo and company identity are managed under Organisation.</p><button class=secondary onclick="page('org')">Open Organisation & Branding</button></div><div class="card"><div class="bar"><div><span class="eyebrow">DATA MANAGEMENT</span><h2>Backup & restore</h2><p class="muted">Use a full backup to move your current local/master data to Render. A backup contains the application database and uploaded files. Restoring replaces the destination data, so always make a backup first.</p></div><span class="pill">Administrator only</span></div><div class="backup-actions"><button onclick="downloadFullBackup()">⬇ Download Full Backup</button><label class="button secondary">⬆ Restore Full Backup<input id="backupFile" type="file" accept=".zip,application/zip" hidden onchange="restoreFullBackup()"></label></div><div id="backupStatus" class="muted" style="margin-top:12px">Preparing storage information…</div><div class="warning-box" style="margin-top:12px"><b>Important:</b> Restore is a full replacement of the destination database. The server automatically creates a pre-restore backup before replacing it. After a successful restore you will be asked to sign in again.</div></div>`,'settings');loadBackupStatus()}
async function saveSettings(){try{const payload={accent_color:setHeader.value,sidebar_color:setSidebar.value};let d=await api('/api/settings',{method:'PUT',body:JSON.stringify(payload)});state.settings={...state.settings,...payload,...(d.settings||{})};applySettings();settings()}catch(e){alert(e.message)}}
async function loadBackupStatus(){try{const d=await api('/api/storage/status');const s=d.storage||{};const el=document.getElementById('backupStatus');if(el)el.innerHTML=`Database: <b>${esc(s.db_path||'unknown')}</b> • ${Number(s.db_size_bytes||0).toLocaleString()} bytes • ${s.persistent_required?(s.data_dir_mount?'persistent storage detected':'persistent storage NOT detected'): 'local storage mode'}.`}catch(e){const el=document.getElementById('backupStatus');if(el)el.textContent='Storage status unavailable.'}}
async function downloadFullBackup(){try{const r=await fetch('/api/backup/export');if(!r.ok){const d=await r.json().catch(()=>({}));throw Error(d.error||'Backup export failed')}const b=await r.blob();const cd=r.headers.get('Content-Disposition')||'';const m=cd.match(/filename="([^"]+)"/);const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=m?m[1]:'Construction_Control_Backup.zip';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}catch(e){alert(e.message)}}
async function restoreFullBackup(){const f=document.getElementById('backupFile')?.files?.[0];if(!f)return;if(f.size>55*1024*1024){alert('Backup file is larger than 55 MB.');return}if(!confirm('This will replace the current database and uploaded files with the selected backup. A safety backup will be created first. Continue?')){document.getElementById('backupFile').value='';return}try{const fd=new FormData();fd.append('file',f);const r=await fetch('/api/backup/restore',{method:'POST',body:fd});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||'Restore failed');alert('Restore completed. The application will reload and ask you to sign in again.');location.reload()}catch(e){alert(e.message)}finally{const el=document.getElementById('backupFile');if(el)el.value=''}}

function audit(){layout('Audit trail',`<div class=card><h2>Recent events</h2><div class=table>${state.audit.map(a=>`<div class=row><div><b>${esc(a.action)}</b><div class=muted>${esc(a.created_at)} • ${esc(a.user_name||'System')} • ${esc(a.target||'')}</div></div></div>`).join('')||'<p class=muted>No events</p>'}</div></div>`,'audit')}
async function out(){await api('/api/logout',{method:'POST'});login()}
async function start(){try{await load();render()}catch{login()}}
function render(){home()}
start();

async function planning(){
  layout('Programme',`<div class="card planning-shell"><div class="section-head"><div><span class="eyebrow">PROGRAMME CONTROL</span><h2>Programme</h2><p class="muted">Select a project to view, create and control its programme.</p></div></div><label>Project</label><select id="planningProject" onchange="state.projectId=this.value;projectPlanning()"><option value="">Choose a project</option>${state.projects.map(p=>`<option value="${esc(p.id)}" ${p.id===state.projectId?'selected':''}>${esc(p.name)}</option>`).join('')}</select><div id="planningArea"></div></div>`,'planning');
  if(state.projectId){const el=document.getElementById('planningProject');if(el)el.value=state.projectId;await projectPlanning();}
}
async function projectPlanning(){
 const a=document.getElementById('planningArea')||document.getElementById('moduleArea');
 if(!state.projectId){if(a)a.innerHTML='<div class="empty-state">Choose a project above to load its programmes.</div>';return}
 try{let d=await api('/api/plans?project_id='+encodeURIComponent(state.projectId));
 let plans=d.plans.map(p=>`<div class="row programme-row"><div><b>${esc(p.name)}</b><div class="muted">${esc(p.status)}${p.baseline?' • Baseline captured':''}</div></div><button class="secondary" onclick="openPlan('${esc(p.id)}')">Open programme →</button></div>`).join('')||'<div class="empty-state">No programmes yet. Create the first programme for this project.</div>';
 a.innerHTML=`<div class=bar><div><span class="eyebrow">PROJECT PROGRAMME</span><h2>${esc((state.projects.find(p=>p.id===state.projectId)||{}).name||'Project')}</h2></div><button onclick="newPlan()">+ New programme</button></div>${plans}<div id="planArea"></div>`;
 }catch(e){a.innerHTML='<p class=error>'+esc(e.message)+'</p>'}
}
function newPlan(){modal('New programme',`<label>Programme name</label><input id=pn><button onclick="savePlan()">Create</button>`)}
async function savePlan(){try{await api('/api/plans',{method:'POST',body:JSON.stringify({project_id:state.projectId,name:pn.value})});closeModal();projectPlanning()}catch(e){alert(e.message)}}
function taskOptions(tasks,current){return '<option value="">None</option>'+tasks.filter(x=>x.id!==current).map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}
function programmeTabs(id,active){
 const tabs=[
  ['programme','Programme'],
  ['resources','Resources'],
  ['lookahead','Look-ahead'],
  ['comparison','Baseline vs Current'],
  ['integration','Live Progress'],
  ['update','Update Programme'],
  ['calendar','Calendar'],
  ['control','Control Centre']
 ];
 return `<div class="programme-tabs" role="tablist" aria-label="Programme views">${tabs.map(([key,label])=>`<button class="programme-tab ${active===key?'active':''}" role="tab" aria-selected="${active===key?'true':'false'}" onclick="openProgrammeTab('${esc(id)}','${key}')">${label}</button>`).join('')}</div>`;
}
function renderProgrammePanel(id,active,content){
 const el=document.getElementById('planExtra');
 if(!el)return;
 el.innerHTML=`${programmeTabs(id,active)}<div class="programme-tab-content">${content}</div>`;

 el.scrollIntoView({behavior:'smooth',block:'nearest'});
}
function programmeHomeMarkup(id,d,g){
 const critical=g.tasks.filter(t=>t.critical).length;
 const complete=g.tasks.length?Math.round(g.tasks.reduce((a,t)=>a+Number(t.percent_complete||0),0)/g.tasks.length):0;
 const gantt=g.tasks.map(t=>`<div class="ganttrow"><div class="glabel ${t.critical?'critical':''}" title="Activity: ${esc(t.name)}">${esc(t.name)}${t.milestone?' ◆':''}</div><div class="gbar programme-bar" style="--pct:${Math.max(0,Math.min(100,t.percent_complete))}%" title="${esc(t.scheduled_start)} → ${esc(t.scheduled_finish)} | Float ${t.float_days}d"><span>${t.critical?'CRITICAL • ':''}${t.percent_complete}%</span></div><div class="gdates"><b>${esc(t.scheduled_start)} → ${esc(t.scheduled_finish)}</b><br><span class="muted">Float ${t.float_days}d</span></div><div class="task-actions gantt-actions"><button class="secondary" data-help="Open this activity so you can change its details." onclick="editTask('${esc(id)}','${esc(t.id)}')">Edit</button><button class="secondary" data-help="Relocate this activity by changing dates or programme links." onclick="moveTask('${esc(id)}','${esc(t.id)}')">Move</button><button class="danger-button" data-help="Delete this activity after confirmation." onclick="deleteTask('${esc(id)}','${esc(t.id)}')">Delete</button></div></div>`).join('')||'<p class=muted>No activities yet.</p>';
 return `<div class="card programme-help-card"><b>Editing the programme</b><span>Each activity is controlled from the Gantt row: <b>Activity → Progress / Critical Path → Scheduled → Edit / Move / Delete</b>.</span></div><div class="plan-summary"><div class="plan-stat"><span class="muted">Activities</span><b>${g.tasks.length}</b></div><div class="plan-stat"><span class="muted">Average progress</span><b>${complete}%</b></div><div class="plan-stat"><span class="muted">Critical</span><b>${critical}</b></div><div class="plan-stat"><span class="muted">Programme finish</span><b>${esc(g.finish_date||'—')}</b></div></div><h4>Gantt / Programme</h4><div class="gantt-head"><div>Activity</div><div>Progress / critical path</div><div>Scheduled</div><div>Options</div></div><div class="gantt">${gantt}</div>`;
}
async function openPlan(id){
 try{
  let d=await api('/api/plans/'+id),g=await api('/api/plans/'+id+'/gantt');
  const planArea=document.getElementById('planArea');
  if(!planArea) return;
  planArea.innerHTML=`<div class="card programme-shell"><div class="bar"><h3>${esc(d.plan.name)}</h3><div class="plan-toolbar"><button data-help="Add a new activity to this programme." onclick="newTask('${esc(id)}')">+ Activity</button><button class="secondary" data-help="Save the current programme dates as the baseline." onclick="setBaseline('${esc(id)}')">Set baseline</button><button class="secondary" data-help="Show planned manpower loading by day." onclick="showResources('${esc(id)}')">Resources</button><button class="secondary" data-help="Show activities planned in the next 14 days." onclick="showLookahead('${esc(id)}')">Look-ahead</button><button class="secondary" data-help="Compare current programme dates with the saved baseline." onclick="showComparison('${esc(id)}')">Baseline vs Current</button><button class="secondary" data-help="Show programme progress alongside daily control and manpower records." onclick="showIntegration('${esc(id)}')">Live Progress</button><button class="secondary" data-help="Enter and save current percentage-complete updates." onclick="showUpdate('${esc(id)}')">Update Programme</button><button class="secondary" data-help="View and manage working-day calendar exceptions." onclick="showCalendar('${esc(id)}')">Calendar</button><button class="secondary" data-help="Show objective programme control information such as overdue and critical activities." onclick="showControl('${esc(id)}')">Control Centre</button><button class="secondary" data-help="Validate and import programme activities from Excel." onclick="programmeImport('${esc(id)}')">Import Excel</button><button class="secondary" data-help="Download the current programme as an Excel workbook." onclick="programmeExport('${esc(id)}')">Export Excel</button></div></div><div id="planExtra"></div></div>`;
  renderProgrammePanel(id,'programme',programmeHomeMarkup(id,d,g));
 
 }catch(e){const el=document.getElementById('planArea');if(el)el.innerHTML=`<div class="error plan-error"><b>Programme could not be loaded.</b><div>${esc(e.message)}</div><button class="secondary" onclick="projectPlanning()">Back to programmes</button></div>`;else alert(e.message)}
}
async function openProgrammeTab(id,tab){
 if(tab==='programme'){try{let d=await api('/api/plans/'+id),g=await api('/api/plans/'+id+'/gantt');renderProgrammePanel(id,'programme',programmeHomeMarkup(id,d,g));}catch(e){alert(e.message)}return;}
 if(tab==='resources')return showResources(id);
 if(tab==='lookahead')return showLookahead(id);
 if(tab==='comparison')return showComparison(id);
 if(tab==='integration')return showIntegration(id);
 if(tab==='update')return showUpdate(id);
 if(tab==='calendar')return showCalendar(id);
 if(tab==='control')return showControl(id);
}

function newTask(id){modal('New activity',`<label>Activity</label><input id=tn><label>Start</label><input id=ts type=date><label>Finish</label><input id=tf type=date><label>Status</label><select id=txs><option>Starting</option><option>Ongoing</option><option>Held Up</option><option>Finished</option></select><label>Percent complete</label><input id=tp type=number min=0 max=100 value=0><label>Planned men</label><input id=tm type=number min=0 step=0.5 value=0><label>Predecessor</label><select id=tdp><option value="">None</option></select><label>Dependency</label><select id=tdt><option>FS</option><option>SS</option><option>FF</option><option>SF</option></select><label>Lag (working days)</label><input id=tlag type=number min=0 value=0><label>Actual start</label><input id=tas type=date><label>Actual finish</label><input id=taf type=date><label>Milestone</label><select id=tml><option value="0">No</option><option value="1">Yes</option></select><button onclick="saveTask('${esc(id)}')">Add activity</button>`);loadTaskPredecessors(id)}
async function loadTaskPredecessors(id){try{let d=await api('/api/plans/'+id);tdp.innerHTML=taskOptions(d.tasks,'')}catch(e){alert(e.message)}}
async function saveTask(id){try{await api('/api/plans/'+id+'/tasks',{method:'POST',body:JSON.stringify({name:tn.value,start_date:ts.value,finish_date:tf.value,percent_complete:Number(tp.value),planned_men:Number(tm.value),predecessor_id:tdp.value||null,dependency_type:tdt.value,lag_days:Number(tlag.value),actual_start:tas.value||null,actual_finish:taf.value||null,status:txs.value,milestone:tml.value==='1'})});closeModal();openPlan(id)}catch(e){alert(e.message)}}
async function editTask(planId,taskId){try{let d=await api('/api/plans/'+planId),t=d.tasks.find(x=>x.id===taskId);if(!t)throw Error('Activity not found');modal('Edit activity',`<label>Activity</label><input id=tn value="${esc(t.name)}"><div class=form-grid><div><label>Start</label><input id=ts type=date value="${esc(t.start_date)}"></div><div><label>Finish</label><input id=tf type=date value="${esc(t.finish_date)}"></div></div><label>Parent / section</label><select id=tparent>${taskOptions(d.tasks,taskId)}</select><label>Status</label><select id=txs><option ${t.task_status==='Starting'?'selected':''}>Starting</option><option ${t.task_status==='Ongoing'?'selected':''}>Ongoing</option><option ${t.task_status==='Held Up'?'selected':''}>Held Up</option><option ${t.task_status==='Finished'?'selected':''}>Finished</option></select><div class=form-grid><div><label>Percent complete</label><input id=tp type=number min=0 max=100 value="${t.percent_complete}"></div><div><label>Planned men</label><input id=tm type=number min=0 step=0.5 value="${t.planned_men}"></div></div><label>Predecessor</label><select id=tdp>${taskOptions(d.tasks,taskId)}</select><label>Dependency</label><select id=tdt><option>FS</option><option>SS</option><option>FF</option><option>SF</option></select><label>Lag (working days)</label><input id=tlag type=number min=0 value="${t.lag_days||0}"><div class=form-grid><div><label>Actual start</label><input id=tas type=date value="${t.actual_start||''}"></div><div><label>Actual finish</label><input id=taf type=date value="${t.actual_finish||''}"></div></div><label>Notes</label><textarea id=tNotes rows=3>${esc(t.notes||'')}</textarea><label>Milestone</label><select id=tml><option value="0">No</option><option value="1" ${t.milestone?'selected':''}>Yes</option></select><div class=modal-actions><button class=secondary onclick="closeModal()">Cancel</button><button onclick="updateTask('${esc(planId)}','${esc(taskId)}')">Save changes</button></div>`);tparent.value=t.parent_id||'';tdp.value=t.predecessor_id||'';tdt.value=t.dependency_type||'FS'}catch(e){alert(e.message)}}
async function updateTask(planId,taskId){try{await api('/api/plans/'+planId+'/tasks/'+taskId,{method:'PUT',body:JSON.stringify({name:tn.value,start_date:ts.value,finish_date:tf.value,parent_id:tparent.value||null,percent_complete:Number(tp.value),planned_men:Number(tm.value),predecessor_id:tdp.value||null,dependency_type:tdt.value,lag_days:Number(tlag.value),actual_start:tas.value||null,actual_finish:taf.value||null,status:txs.value,milestone:tml.value==='1',notes:tNotes.value||''})});closeModal();openPlan(planId)}catch(e){alert(e.message)}}
async function moveTask(planId,taskId){try{let d=await api('/api/plans/'+planId),t=d.tasks.find(x=>x.id===taskId);if(!t)throw Error('Activity not found');modal('Move activity',`<p class=muted>Change the activity dates or its programme link. The activity keeps its existing name, progress and manpower.</p><div class=form-grid><div><label>New start</label><input id=ms type=date value="${esc(t.start_date)}"></div><div><label>New finish</label><input id=mf type=date value="${esc(t.finish_date)}"></div></div><label>Parent / section</label><select id=mp>${taskOptions(d.tasks,taskId)}</select><label>Predecessor</label><select id=mdp>${taskOptions(d.tasks,taskId)}</select><label>Dependency</label><select id=mdt><option>FS</option><option>SS</option><option>FF</option><option>SF</option></select><label>Lag (working days)</label><input id=mlag type=number min=0 value="${t.lag_days||0}"><div class=modal-actions><button class=secondary onclick="closeModal()">Cancel</button><button onclick="applyMove('${esc(planId)}','${esc(taskId)}')">Move activity</button></div>`);mp.value=t.parent_id||'';mdp.value=t.predecessor_id||'';mdt.value=t.dependency_type||'FS'}catch(e){alert(e.message)}}
async function applyMove(planId,taskId){try{await api('/api/plans/'+planId+'/tasks/'+taskId,{method:'PUT',body:JSON.stringify({start_date:ms.value,finish_date:mf.value,parent_id:mp.value||null,predecessor_id:mdp.value||null,dependency_type:mdt.value,lag_days:Number(mlag.value||0)})});closeModal();openPlan(planId)}catch(e){alert(e.message)}}
async function deleteTask(planId,taskId){try{let d=await api('/api/plans/'+planId),t=d.tasks.find(x=>x.id===taskId);if(!t)return alert('Activity not found');if(!confirm(`Delete activity “${t.name}”? This cannot be undone.`))return;await api('/api/plans/'+planId+'/tasks/'+taskId,{method:'DELETE'});openPlan(planId)}catch(e){alert(e.message)}}
async function setBaseline(id){try{await api('/api/plans/'+id+'/baseline',{method:'POST'});openPlan(id)}catch(e){alert(e.message)}}
async function showResources(id){try{let d=await api('/api/plans/'+id+'/resources');let rows=Object.entries(d.daily).map(([day,men])=>`<tr><td>${esc(day)}</td><td>${Number(men).toFixed(1)}</td></tr>`).join('');let content=`<h4>Resource loading</h4><p class=muted>Peak planned manpower: ${Number(d.peak_men).toFixed(1)} men</p><div class=resource-table><table><tr><th>Date</th><th>Planned men</th></tr>${rows}</table></div>`;renderProgrammePanel(id,'resources',content); }catch(e){alert(e.message)}}
async function showComparison(id){try{let d=await api('/api/plans/'+id+'/comparison');let rows=d.tasks.map(t=>`<div class=row><div><b>${esc(t.name)}</b><div class=muted>Baseline ${esc(t.baseline_start)} → ${esc(t.baseline_finish)} • Current ${esc(t.current_start)} → ${esc(t.current_finish)} • Scheduled finish variance ${t.scheduled_finish_variance_days}d</div></div></div>`).join('')||'<p class=muted>No baseline captured yet. Set a baseline first.</p>';let content=`<h4>Baseline vs current</h4><p class=muted>Baseline finish: ${esc(d.baseline_finish||'—')} • Current scheduled finish: ${esc(d.current_finish||'—')} • Weighted progress: ${d.programme_progress}%</p>${rows}`;renderProgrammePanel(id,'comparison',content); }catch(e){alert(e.message)}}
async function showIntegration(id){try{let d=await api('/api/plans/'+id+'/integration');let days=Object.entries(d.manpower.by_day).map(([day,v])=>`<tr><td>${esc(day)}</td><td>${v.planned_men.toFixed(1)}</td><td>${v.actual_men.toFixed(1)}</td><td>${v.man_hours.toFixed(1)}</td></tr>`).join('');let content=`<h4>Live construction progress</h4><div class=plan-summary><div class=plan-stat><span class=muted>Programme progress</span><b>${d.programme_progress}%</b></div><div class=plan-stat><span class=muted>Daily logs</span><b>${d.daily_control.days_logged}</b></div><div class=plan-stat><span class=muted>Completed entries</span><b>${d.daily_control.completed_activity_entries}</b></div><div class=plan-stat><span class=muted>Man-hours</span><b>${Object.values(d.manpower.by_day).reduce((a,v)=>a+v.man_hours,0).toFixed(1)}</b></div></div><div class=resource-table><table><tr><th>Date</th><th>Planned</th><th>Actual</th><th>Man-hours</th></tr>${days}</table></div>`;renderProgrammePanel(id,'integration',content); }catch(e){alert(e.message)}}
async function showLookahead(id){try{let d=await api('/api/plans/'+id+'/lookahead?days=14');let rows=d.tasks.map(t=>`<div class=row><div><b>${esc(t.name)}</b><div class=muted>${esc(t.scheduled_start)} → ${esc(t.scheduled_finish)} • ${t.percent_complete}%</div></div></div>`).join('')||'<p class=muted>No activities in the next 14 days.</p>';let content=`<h4>14-day look-ahead</h4>${rows}`;renderProgrammePanel(id,'lookahead',content); }catch(e){alert(e.message)}}
async function showUpdate(id){try{let d=await api('/api/plans/'+id);let rows=d.tasks.map(t=>`<div class="row"><div style="flex:1"><b>${esc(t.name)}</b><div class="muted">Planned ${esc(t.start_date)} → ${esc(t.finish_date)} • Actual ${esc(t.actual_start||'—')} → ${esc(t.actual_finish||'—')}</div></div><div><input id="up_${esc(t.id)}" type="number" min="0" max="100" value="${t.percent_complete}" style="width:90px" title="Percent complete"></div></div>`).join('')||'<p class=muted>No activities.</p>';let content=`<h4>Programme update</h4><div class=formgrid><label>Update date<input id="upDate" type=date value="${new Date().toISOString().slice(0,10)}"></label><label>Note<input id="upNote" placeholder="Weekly progress update"></label></div><p class=muted>Enter current percentage complete for each activity, then save the update.</p>${rows}<button onclick="saveUpdate('${esc(id)}')">Save programme update</button>`;renderProgrammePanel(id,'update',content); }catch(e){alert(e.message)}}
async function saveUpdate(id){try{let d=await api('/api/plans/'+id),tasks=d.tasks.map(t=>({id:t.id,percent_complete:Number(document.getElementById('up_'+t.id).value)}));await api('/api/plans/'+id+'/update',{method:'POST',body:JSON.stringify({update_date:upDate.value,note:upNote.value,tasks})});openPlan(id)}catch(e){alert(e.message)}}
async function showUpdateHistory(id){try{let d=await api('/api/plans/'+id+'/updates');let rows=d.updates.map(u=>{let changed=u.tasks.length, avg=changed?Math.round(u.tasks.reduce((a,t)=>a+Number(t.percent_complete),0)/changed):0;return `<div class="row"><div><b>${esc(u.update_date)}</b><div class="muted">${changed} activities updated • ${avg}% average • ${esc(u.user_name||'')}</div>${u.note?`<div>${esc(u.note)}</div>`:''}</div></div>`}).join('')||'<p class=muted>No programme updates recorded yet.</p>';document.getElementById('planExtra').innerHTML=`<h4>Programme update history</h4>${rows}`}catch(e){alert(e.message)}}
async function showPerformance(id){try{let d=await api('/api/plans/'+id+'/performance');let trend=d.trend.map(x=>`<tr><td>${esc(x.date)}</td><td>${x.progress}%</td><td>${esc(x.note||'')}</td></tr>`).join('')||'<tr><td colspan=3>No snapshots yet.</td></tr>';let mp=d.manpower.map(x=>`<tr><td>${esc(x.date)}</td><td>${x.planned_men.toFixed(1)}</td><td>${x.actual_men.toFixed(1)}</td><td>${x.variance_men.toFixed(1)}</td><td>${x.man_hours.toFixed(1)}</td></tr>`).join('')||'<tr><td colspan=5>No manpower records.</td></tr>';document.getElementById('planExtra').innerHTML=`<h4>Programme performance</h4><div class=plan-summary><div class=plan-stat><span class=muted>Current progress</span><b>${d.current_progress}%</b></div><div class=plan-stat><span class=muted>Updates</span><b>${d.update_count}</b></div><div class=plan-stat><span class=muted>Planned men entries</span><b>${d.manpower_totals.planned_men}</b></div><div class=plan-stat><span class=muted>Actual men entries</span><b>${d.manpower_totals.actual_men}</b></div></div><h4>Progress history</h4><div class=resource-table><table><tr><th>Date</th><th>Progress</th><th>Note</th></tr>${trend}</table></div><h4>Manpower performance</h4><div class=resource-table><table><tr><th>Date</th><th>Planned</th><th>Actual</th><th>Variance</th><th>Man-hours</th></tr>${mp}</table></div>`}catch(e){alert(e.message)}}
async function showControl(id){try{let d=await api('/api/plans/'+id+'/control');let overdue=d.overdue.map(t=>`<div class=row><div><b>${esc(t.name)}</b><div class=muted>Finish ${esc(t.finish_date)} • ${t.percent_complete}% • ${t.days_overdue} day(s) overdue</div></div></div>`).join('')||'<p class=muted>No overdue incomplete activities as of '+esc(d.as_of)+'.</p>';let critical=d.critical_incomplete.map(t=>`<div class=row><div><b>${esc(t.name)}</b><div class=muted>Critical path • Finish ${esc(t.finish_date)} • ${t.percent_complete}%</div></div></div>`).join('')||'<p class=muted>No incomplete critical-path activities identified.</p>';let content=`<h4>Programme Control Centre</h4><p class=muted>Objective programme status as of ${esc(d.as_of)}. This report shows dates, progress and dependency facts; it does not assign a subjective health score.</p><div class=plan-summary><div class=plan-stat><span class=muted>Progress</span><b>${d.programme_progress}%</b></div><div class=plan-stat><span class=muted>Total activities</span><b>${d.activity_counts.total}</b></div><div class=plan-stat><span class=muted>Completed</span><b>${d.activity_counts.completed}</b></div><div class=plan-stat><span class=muted>Overdue</span><b>${d.overdue.length}</b></div></div><p class=muted>Baseline finish: ${esc(d.baseline_finish||'—')} • Current finish: ${esc(d.current_finish||'—')} • Finish variance: ${d.baseline_finish_variance_days===null?'—':d.baseline_finish_variance_days+' days'}</p><h4>Overdue incomplete activities</h4>${overdue}<h4>Incomplete critical-path activities</h4>${critical}`;renderProgrammePanel(id,'control',content); }catch(e){alert(e.message)}}
async function programmeImport(id){modal('Programme Excel round-trip',`<p class=muted>Use <b>Export Excel</b> to download the live programme, edit it in Excel, then upload it here. Existing Activity IDs are updated; new Activity IDs are added. The system validates the complete workbook before anything is changed.</p><button class=secondary onclick="downloadProgrammeTemplate('${esc(id)}')">Download blank import template</button><label>Excel file<input id=piFile type=file accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"></label><button onclick="previewProgrammeFile('${esc(id)}')">Validate & Preview</button><div id="piResult"></div>`)}
async function downloadProgrammeTemplate(id){try{let r=await fetch('/api/plan-import/templates?plan_id='+encodeURIComponent(id));if(!r.ok){let d=await r.json().catch(()=>({}));throw Error(d.error||'Template download failed')}let b=await r.blob(),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='Construction_Control_Programme_Import_Template.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}catch(e){alert(e.message)}}
async function programmeExport(id){try{let r=await fetch('/api/plan-export/'+encodeURIComponent(id));if(!r.ok){let d=await r.json().catch(()=>({}));throw Error(d.error||'Export failed')}let b=await r.blob(),cd=r.headers.get('Content-Disposition')||'',m=cd.match(/filename="([^"]+)"/),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=m?m[1]:'Construction_Control_Programme.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}catch(e){alert(e.message)}}
async function previewProgrammeFile(id){let f=piFile.files[0];if(!f){alert('Choose an Excel file');return}if(f.size>12*1024*1024){alert('File is larger than 12 MB');return}try{let fd=new FormData();fd.append('file',f);let r=await fetch('/api/plan-import/roundtrip?plan_id='+encodeURIComponent(id)+'&commit=0',{method:'POST',body:fd});let d=await r.json().catch(()=>({}));if(!r.ok)throw Object.assign(Error(d.error||'Validation failed'),{data:d});let rows=(d.changes||[]).map(x=>`<tr><td>${esc(x.row)}</td><td>${esc(x.activity_id)}</td><td>${x.action==='update'?'Update':'Add'}</td><td>${esc(x.activity)}</td></tr>`).join('');piResult.innerHTML=`<h4>Validation passed</h4><p>${d.updates} update(s) • ${d.adds} add(s) • ${d.rows_processed} row(s) processed</p><div class=resource-table><table><tr><th>Row</th><th>Activity ID</th><th>Action</th><th>Activity</th></tr>${rows}</table></div><button onclick="commitProgrammeFile('${esc(id)}')">Confirm & Apply Changes</button>`}catch(e){let d=e.data||{};piResult.innerHTML='<p class=error>'+esc(e.message)+(d.errors?.length?'<br>'+d.errors.slice(0,20).map(x=>`Row ${esc(x.row)}: ${esc(x.errors.join(', '))}`).join('<br>'):'')+'</p>'}}
async function commitProgrammeFile(id){let f=piFile.files[0];if(!f)return;try{let fd=new FormData();fd.append('file',f);let r=await fetch('/api/plan-import/roundtrip?plan_id='+encodeURIComponent(id)+'&commit=1',{method:'POST',body:fd});let d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||'Import failed');closeModal();openPlan(id)}catch(e){alert(e.message)}}
let programmeCalendarMonths={};
let programmeCalendarData={};
function calendarDateKey(y,m,d){return `${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`}
function calendarMonthLabel(y,m){return new Date(Date.UTC(y,m,1)).toLocaleDateString('en-GB',{month:'long',year:'numeric',timeZone:'UTC'}).toUpperCase()}
function calendarWeekNumber(date){const d=new Date(Date.UTC(date.getUTCFullYear(),date.getUTCMonth(),date.getUTCDate()));const day=(d.getUTCDay()+6)%7;d.setUTCDate(d.getUTCDate()-day+3);const first=new Date(Date.UTC(d.getUTCFullYear(),0,4));return 1+Math.round(((d-first)/86400000-3+((first.getUTCDay()+6)%7))/7)}
function calendarTaskTab(t,key,id){const start=t.scheduled_start,end=t.scheduled_finish;if(!start||!end||key<start||key>end)return '';const status=(t.task_status||t.status||'').toLowerCase().replace(/\s+/g,'-');const pct=Number(t.percent_complete||0);return `<button class="calendar-task-tab ${status} ${t.critical?'critical':''}" title="${esc(t.name)} • ${pct}% • ${esc(start)} → ${esc(end)}" onclick="event.stopPropagation();editTask('${esc(id)}','${esc(t.id)}')">${t.critical?'◆ ':''}${esc(t.name)}<span>${pct}%</span></button>`}
function calendarDayModal(id,key){const data=programmeCalendarData[id]||{};const g=data.g||{tasks:[]},ex=data.ex||{exceptions:[]};const tasks=(g.tasks||[]).filter(t=>t.scheduled_start&&t.scheduled_finish&&key>=t.scheduled_start&&key<=t.scheduled_finish);const exceptions=(ex.exceptions||[]).filter(x=>x.exception_date===key);const taskRows=tasks.map(t=>`<div class="calendar-detail-row"><div><b>${esc(t.name)}</b><small>${esc(t.scheduled_start)} → ${esc(t.scheduled_finish)} • ${Number(t.percent_complete||0)}% • ${esc(t.task_status||'')}</small></div><button class="secondary" onclick="closeModal();editTask('${esc(id)}','${esc(t.id)}')">Edit</button></div>`).join('')||'<p class=muted>No programme activities on this date.</p>';const exRows=exceptions.map(x=>`<div class="calendar-detail-row"><div><b>${x.working?'Working day':'Non-working day'}</b><small>${esc(x.reason||'No reason entered')}</small></div><button class="secondary" onclick="closeModal();deleteCalendar('${esc(x.id)}','${esc(id)}')">Delete</button></div>`).join('');modal(new Date(key+'T00:00:00Z').toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}),`<div class="calendar-detail-list"><h4>Programme activities</h4>${taskRows}${exRows?`<h4>Calendar exceptions</h4>${exRows}`:''}</div><hr><h4>Add calendar exception</h4><div class=formgrid><label>Type<select id=ceWork><option value="0">Non-working</option><option value="1">Working</option></select></label><label>Reason<input id=ceReason placeholder="Holiday / shutdown / working Saturday"></label></div><button onclick="saveCalendar('${esc(id)}','${esc(key)}')">Save exception</button>`)}
async function showCalendar(id,monthOverride){try{let d=await api('/api/plans/'+id),ex=await api('/api/plan-calendar?project_id='+encodeURIComponent(state.projectId)+'&plan_id='+encodeURIComponent(id)),g=await api('/api/plans/'+id+'/gantt');window.currentProgrammePlanId=id;programmeCalendarData[id]={g,ex};let base=monthOverride||programmeCalendarMonths[id]||new Date().toISOString().slice(0,7);let [y,m0]=base.split('-').map(Number);let m=m0-1;programmeCalendarMonths[id]=`${y}-${String(m+1).padStart(2,'0')}`;const first=new Date(Date.UTC(y,m,1)),last=new Date(Date.UTC(y,m+1,0));const startOffset=first.getUTCDay(),days=last.getUTCDate(),total=Math.ceil((startOffset+days)/7)*7;const exceptionsByDate={};(ex.exceptions||[]).forEach(x=>exceptionsByDate[x.exception_date]=x);let header=['SUNDAY','MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY','SATURDAY'].map(x=>`<div class="calendar-head-day">${x}</div>`).join('');let bodyCells='';for(let r=0;r<total/7;r++){const weekStart=new Date(Date.UTC(y,m,1-startOffset+r*7));bodyCells+=`<div class="calendar-week-number">${calendarWeekNumber(weekStart)}</div>`;for(let c=0;c<7;c++){const idx=r*7+c,day=idx-startOffset+1,dt=new Date(Date.UTC(y,m,day)),inMonth=day>=1&&day<=days,key=calendarDateKey(dt.getUTCFullYear(),dt.getUTCMonth(),dt.getUTCDate()),tasks=inMonth?(g.tasks||[]).filter(t=>t.scheduled_start&&t.scheduled_finish&&key>=t.scheduled_start&&key<=t.scheduled_finish):[],exc=inMonth?exceptionsByDate[key]:null,tabs=tasks.slice(0,5).map(t=>calendarTaskTab(t,key,id)).join('')+(tasks.length>5?`<button class="calendar-more-tab" onclick="event.stopPropagation();calendarDayModal('${esc(id)}','${esc(key)}')">+${tasks.length-5} more</button>`:'');bodyCells+=`<div class="calendar-cell ${inMonth?'':'outside'} ${exc&&!exc.working?'non-working':''}" data-date="${key}" onclick="calendarDayModal('${esc(id)}','${esc(key)}')"><div class="calendar-date-head"><span class="calendar-date-number">${dt.getUTCDate()}</span>${inMonth?`<button class="calendar-add" title="Add calendar exception" onclick="event.stopPropagation();calendarDayModal('${esc(id)}','${esc(key)}')">+</button>`:''}</div>${exc?`<div class="calendar-exception-tab ${exc.working?'working':'nonworking'}">${exc.working?'Working':'Non-working'}${exc.reason?' • '+esc(exc.reason):''}</div>`:''}<div class="calendar-task-list">${tabs}</div></div>`}}renderProgrammePanel(id,'calendar',`<div class="programme-calendar"><div class="calendar-month-bar"><button class="secondary" onclick="showCalendar('${esc(id)}',calendarShiftMonth('${esc(id)}',-1))">‹</button><div><h2>${calendarMonthLabel(y,m)}</h2><span>Programme calendar • click a date or activity tab for details</span></div><button class="secondary" onclick="showCalendar('${esc(id)}',calendarShiftMonth('${esc(id)}',1))">›</button></div><div class="calendar-grid calendar-header"><div class="calendar-week-head">Wk</div>${header}</div><div class="calendar-grid calendar-body">${bodyCells}</div></div>`)}catch(e){alert(e.message)}}
function calendarShiftMonth(id,delta){let base=programmeCalendarMonths[id]||new Date().toISOString().slice(0,7);let [y,m]=base.split('-').map(Number);const d=new Date(Date.UTC(y,m-1+delta,1));const out=`${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}`;programmeCalendarMonths[id]=out;return out}
async function saveCalendar(id,dateOverride){try{let date=dateOverride||(document.getElementById('ceDate')||{}).value;if(!date){alert('Choose a date');return}await api('/api/plan-calendar',{method:'POST',body:JSON.stringify({project_id:state.projectId,plan_id:id,exception_date:date,working:ceWork.value==='1',reason:ceReason.value})});closeModal();showCalendar(id,dateOverride?dateOverride.slice(0,7):programmeCalendarMonths[id])}catch(e){alert(e.message)}}
async function deleteCalendar(eid,id){try{await api('/api/plan-calendar/'+eid,{method:'DELETE'});closeModal();showCalendar(id)}catch(e){alert(e.message)}}

async function dailySiteControl(){
  if(!state.projects.length){layout('Daily Site Control','<div class="card"><h2>No projects available</h2></div>','daily');return}
  if(!state.projectId) state.projectId=state.projects[0].id;
  const day=new Date().toISOString().slice(0,10);
  try{const d=await api('/api/daily-site-control?project_id='+encodeURIComponent(state.projectId)+'&date='+day); renderDailySiteControl(d)}catch(e){alert(e.message)}
}
function renderDailySiteControl(d){
 const p=d.project, att={}; (d.attendance||[]).forEach(x=>att[x.staff_id]=x);
 const activeStaff=(d.staff||[]).filter(x=>x.staff_active!==0);
 const staff=activeStaff.map(s=>{const a=att[s.id]||{};return `<div class="attendance-row"><div><b>${esc(s.name)}</b><small>${esc(s.assignment_role||s.position)} • ${esc(s.staff_ref)}</small></div><label class="check"><input type="checkbox" class="att-on" data-sid="${esc(s.id)}" ${a.onsite?'checked':''}> On site</label><input class="att-hours" data-sid="${esc(s.id)}" type="number" min="0" max="24" step="0.5" value="${a.hours??''}" placeholder="Hours"></div>`}).join('')||'<p class=muted>No active staff. Add staff before using individual attendance.</p>';
 const starting=d.tasks.filter(x=>x.bucket==='starting'), late=d.tasks.filter(x=>x.bucket==='late_start'), active=d.tasks.filter(x=>x.bucket==='active'), tomorrow=d.tasks.filter(x=>x.start_date===new Date(new Date(d.date+'T12:00:00').getTime()+86400000).toISOString().slice(0,10));
 const taskRows=[...late,...starting,...active].map(t=>`<div class="daily-task ${t.status==='Held Up'||t.bucket==='late_start'?'late':''}"><div><b>${esc(t.name)}</b><small>${t.status==='Held Up'?'Held up':t.bucket==='starting'?'Starts today':t.bucket==='late_start'?'Should have started':'Active'} • Planned ${Number(t.planned_men).toFixed(1)} men • ${esc(t.start_date)} → ${esc(t.finish_date)}</small></div><div class="task-actions"><select class="task-status" data-tid="${esc(t.id)}">${['Starting','Ongoing','Held Up','Finished'].map(s=>`<option ${t.status===s?'selected':''}>${s}</option>`).join('')}</select><input class="task-percent" data-tid="${esc(t.id)}" type="number" min="0" max="100" value="${t.percent_complete}" title="% complete"><select class="task-reason" data-tid="${esc(t.id)}"><option value="">Held-up reason</option>${['Material','Design/RFI','Access','Labour','Permit','Client','Other'].map(s=>`<option ${t.held_up_reason===s?'selected':''}>${s}</option>`).join('')}</select><input class="task-note" data-tid="${esc(t.id)}" value="${esc(t.status_notes||'')}" placeholder="Update note"></div></div>`).join('')||'<p class=muted>No active programme tasks for today.</p>';
 const body=`<div class="daily-head"><div><span class="eyebrow">DAILY SITE CONTROL</span><h2>${esc(p.name)}</h2><p class="muted">${esc(d.date)} • morning control — record only what changed.</p></div><select id="dailyProject" onchange="state.projectId=this.value;dailySiteControl()">${state.projects.map(x=>`<option value="${esc(x.id)}" ${x.id===state.projectId?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>
 <div class="morning-steps"><div class="morning-step active"><b>1</b><span>People</span></div><div class="morning-step"><b>2</b><span>Work</span></div><div class="morning-step"><b>3</b><span>Facts</span></div><div class="morning-step"><b>4</b><span>Save</span></div></div>
 <div class="daily-quickbar morning-bar"><div><span class="eyebrow">TODAY</span><b>${esc(d.date)}</b><span class="muted">Complete the four steps below, then save once.</span></div><div class="daily-quick-actions"><button class="secondary" onclick="setAllAttendance(true)">✓ Everyone on site</button><button class="secondary" onclick="setAllAttendance(false)">Clear</button><button onclick="saveDailySiteControl('${esc(p.id)}','${esc(d.date)}')">✓ Save today's control</button></div></div>
 <div class="daily-kpis"><div><span>Project manloader</span><b>${Number(p.manloader||0).toFixed(1)}</b><small>baseline</small></div><div><span>Planned today</span><b>${Number(d.planned_men||0).toFixed(1)}</b><small>from programme</small></div><div><span>On site</span><b id="dailyActual">${d.actual_men}</b><small>attendance</small></div><div><span>Variance</span><b id="dailyVariance">${(Number(d.actual_men)-Number(d.planned_men)).toFixed(1)}</b><small>actual − planned</small></div><div><span>Man-hours</span><b id="dailyHours">${Number(d.man_hours).toFixed(1)}</b><small>today</small></div></div>
 <div class="daily-progress-strip"><div><b>Morning control</b><span id="morningProgressText">${d.daily.status==='Complete'?'Ready for review':'Start with attendance'}</span></div><div class="progress"><span id="morningProgressBar" style="width:${d.daily.status==='Complete'?100:25}%"></span></div></div>
 <div class="card daily-card"><div class="section-head"><div><span class="eyebrow">PLAN AHEAD</span><h2>Starting tomorrow</h2></div></div>${tomorrow.map(t=>`<div class="row"><div><b>${esc(t.name)}</b><div class="muted">${esc(t.start_date)} • ${Number(t.planned_men).toFixed(1)} planned • ${esc(t.status)}</div></div></div>`).join('')||'<p class="muted">No tasks starting tomorrow.</p>'}</div>
 <div class="daily-grid"><section>
 <div class="card daily-card morning-card"><div class="section-head"><div><span class="eyebrow">1 • PEOPLE</span><h2>Who's on site?</h2></div><span class="muted">Tap once per person</span></div><div id="attendanceList">${staff}</div></div>
 <div class="card daily-card morning-card"><div class="section-head"><div><span class="eyebrow">2 • WORK</span><h2>What is happening today?</h2></div><span class="muted">Only update changed tasks</span></div>${late.length?`<div class="notice-danger"><b>🚨 ${late.length} task${late.length===1?'':'s'} should have started</b><span>Update these first.</span></div>`:''}${starting.length?`<h3>Starting today</h3>`:''}${taskRows}</div>
 <div class="card daily-card morning-card"><div class="section-head"><div><span class="eyebrow">3 • FACTS</span><h2>What changed?</h2></div><span class="muted">Leave blank if nothing changed</span></div><div class="formgrid"><label>Daily status<select id="dcStatus"><option ${d.daily.status==='Complete'?'selected':''}>Complete</option><option ${d.daily.status==='Draft'?'selected':''}>Draft</option></select></label><label>Safety check<select id="dcSafety"><option ${d.daily.safety_check==='Completed'?'selected':''}>Completed</option><option ${d.daily.safety_check==='Not completed'?'selected':''}>Not completed</option><option ${!['Completed','Not completed'].includes(d.daily.safety_check)?'selected':''}>Not recorded</option></select></label></div><label>Completed work<textarea id="dcCompleted" rows="2" placeholder="What was completed today?">${esc(d.daily.completed_activities||'')}</textarea></label><label>Delays / problems<textarea id="dcDelays" rows="2" placeholder="Anything that stopped or slowed work?">${esc(d.daily.delays||'')}</textarea></label><label>Constraints<textarea id="dcConstraints" rows="2" placeholder="Access, design, materials, labour...">${esc(d.daily.constraints||'')}</textarea></label><label>Notes<textarea id="dcNotes" rows="2" placeholder="Anything else worth recording?">${esc(d.daily.notes||'')}</textarea></label></div>
 <div class="card daily-card morning-card quick-capture"><div class="section-head"><div><span class="eyebrow">QUICK CAPTURE</span><h2>Something needs attention?</h2></div><span class="muted">Record it once</span></div><div class="quick-capture-grid"><label>Type<select id="qiType"><option>Actions</option><option>RFIs</option><option>Risks</option><option>Snags</option></select></label><label>Title<input id="qiTitle" placeholder="e.g. Tray delivery delayed"></label><label class="wide">What happened?<textarea id="qiDescription" rows="2" placeholder="Brief description"></textarea></label></div><div class="quick-capture-actions"><button class="secondary" onclick="createDailyIssue('${esc(p.id)}','${esc(d.date)}')">+ Add issue</button><label class="photo-input">📷 Add site photo<input id="dailyPhoto" type="file" accept="image/*" capture="environment"></label></div></div>
 </section>
 <aside><div class="card daily-card morning-save"><span class="eyebrow">4 • FINISH</span><h2>Ready to save?</h2><p class="muted">One save records attendance, task progress and today's site control together.</p><button class="big-save" onclick="saveDailySiteControl('${esc(p.id)}','${esc(d.date)}')">✓ SAVE TODAY'S CONTROL</button><div class="save-checks"><span>✓ People</span><span>✓ Programme</span><span>✓ Site facts</span><span>✓ Audit record</span></div></div><div class="card daily-card"><span class="eyebrow">LIVE CONTROLS</span><h2>Needs attention</h2><div class="daily-control-list"><button onclick="openDashboardModule('RFIs','${esc(p.id)}')">RFIs <b>${d.controls.RFIs||0}</b></button><button onclick="openDashboardModule('Risks','${esc(p.id)}')">Risks <b>${d.controls.Risks||0}</b></button><button onclick="openDashboardModule('Actions','${esc(p.id)}')">Actions <b>${d.controls.Actions||0}</b></button><button onclick="openDashboardModule('Snags','${esc(p.id)}')">Snags <b>${d.controls.Snags||0}</b></button></div></div></aside></div>`;
 layout('Daily Site Control',body,'daily');
 document.querySelectorAll('.task-status').forEach(s=>s.onchange=()=>{const n=document.querySelector(`.task-percent[data-tid="${CSS.escape(s.dataset.tid)}"]`);if(s.value==='Starting')n.value=0;if(s.value==='Finished')n.value=100;const r=document.querySelector(`.task-reason[data-tid="${CSS.escape(s.dataset.tid)}"]`);if(r)r.disabled=s.value!=='Held Up';updateMorningProgress();});
 document.querySelectorAll('.task-status').forEach(s=>s.dispatchEvent(new Event('change')));
 document.querySelectorAll('.task-percent').forEach(x=>x.oninput=updateMorningProgress);
 document.querySelectorAll('.att-on,.att-hours').forEach(el=>el.onchange=()=>{refreshDailyAttendance();updateMorningProgress()});
 refreshDailyAttendance(); updateMorningProgress();
}
function updateMorningProgress(){
 const hasPeople=[...document.querySelectorAll('.att-on')].some(x=>x.checked);
 const tasks=[...document.querySelectorAll('.task-percent')];
 const hasTask=tasks.length===0||tasks.some(x=>Number(x.value||0)>0);
 const facts=!!(document.getElementById('dcCompleted')?.value.trim()||document.getElementById('dcDelays')?.value.trim()||document.getElementById('dcConstraints')?.value.trim()||document.getElementById('dcNotes')?.value.trim());
 const safety=document.getElementById('dcSafety')?.value==='Completed';
 const score=(hasPeople?25:0)+(hasTask?25:0)+(facts||safety?25:0)+(document.getElementById('dcStatus')?.value==='Complete'?25:0);
 const bar=document.getElementById('morningProgressBar'),txt=document.getElementById('morningProgressText'); if(bar)bar.style.width=score+'%'; if(txt)txt.textContent=score===100?'Ready to save':score+'% complete — finish the remaining morning steps';
}

function setAllAttendance(on){document.querySelectorAll('.att-on').forEach(x=>x.checked=on); if(on){document.querySelectorAll('.att-hours').forEach(x=>{if(!x.value)x.value=8})} refreshDailyAttendance();}
function refreshDailyAttendance(){let n=0,h=0;document.querySelectorAll('.att-on').forEach(x=>{if(x.checked)n++});document.querySelectorAll('.att-hours').forEach(x=>{const on=document.querySelector(`.att-on[data-sid="${CSS.escape(x.dataset.sid)}"]`);if(on?.checked)h+=Number(x.value||0)});const a=document.getElementById('dailyActual'),hh=document.getElementById('dailyHours'),v=document.getElementById('dailyVariance');if(a)a.textContent=n;if(hh)hh.textContent=h.toFixed(1);if(v){const planned=Number(document.querySelector('.daily-kpis div:nth-child(2) b')?.textContent||0);v.textContent=(n-planned).toFixed(1)}}
async function saveDailySiteControl(pid,day){
 try{
  const attendance=[];
  document.querySelectorAll('.att-on').forEach(x=>{
   const sid=x.dataset.sid;
   const hours=document.querySelector(`.att-hours[data-sid="${CSS.escape(sid)}"]`);
   attendance.push({staff_id:sid,onsite:x.checked,hours:Number(hours?.value||0)});
  });
  const tasks=[];
  document.querySelectorAll('.task-percent').forEach(x=>{const tid=x.dataset.tid;tasks.push({id:tid,percent_complete:Number(x.value||0),status:document.querySelector(`.task-status[data-tid="${CSS.escape(tid)}"]`)?.value,held_up_reason:document.querySelector(`.task-reason[data-tid="${CSS.escape(tid)}"]`)?.value,status_notes:document.querySelector(`.task-note[data-tid="${CSS.escape(tid)}"]`)?.value||''})});
  const saved=await api('/api/daily-site-control',{
   method:'POST',
   body:JSON.stringify({
    project_id:pid,date:day,attendance,tasks,status:dcStatus.value,safety_check:dcSafety.value,
    completed_activities:dcCompleted.value,delays:dcDelays.value,constraints:dcConstraints.value,notes:dcNotes.value
   })
  });
  const photo=document.getElementById('dailyPhoto')?.files?.[0];
  if(photo&&saved.record_id) await uploadDailyPhoto(pid,saved.record_id,photo);
  await dailySiteControl();
  alert('Daily Site Control saved.');
 }catch(e){alert(e.message)}
}
async function staffPage(){
 try{
  const [d,a]=await Promise.all([api('/api/staff?active=all'),api('/api/project-assignments')]);
  window._staffCache=d.staff;
  const trainingCounts={};
  await Promise.all(d.staff.map(async s=>{try{const t=await api('/api/staff/'+encodeURIComponent(s.id)+'/training');trainingCounts[s.id]=(t.training||[]).length}catch(_){trainingCounts[s.id]=0}}));
  const rows=d.staff.map(s=>{
   const as=a.assignments.filter(x=>x.staff_id===s.id&&x.assignment_status==='Active');
   const level=s.labour_level||s.position; const bg=STAFF_LEVEL_COLORS[level]||'#fff';
   return `<div class="row staff-row"><div style="flex:1"><div style="display:flex;gap:10px;align-items:center"><span style="display:inline-block;width:14px;height:14px;border-radius:3px;background:${bg};border:1px solid #777"></span><b>${esc(s.name)}</b></div><div class="muted">${esc(s.staff_ref)} • ${esc(level)}${s.badge_type?' • '+esc(s.badge_type):''}${s.source_group?' • '+esc(s.source_group):''}${as.length?' • '+as.map(x=>esc(x.project_name)+' ('+esc(x.start_date)+(x.finish_date?'–'+esc(x.finish_date):'')+')').join(', '):' • Unassigned'} • ${trainingCounts[s.id]||0} training record${(trainingCounts[s.id]||0)===1?'':'s'}</div></div><span class="pill ${s.active?'':'off'}">${s.active?'Active':'Inactive'}</span><button class="secondary" title="View, add and edit this person's training records." onclick="trainingStaff('${esc(s.id)}')">Training (${trainingCounts[s.id]||0})</button><button class="secondary" title="Create or change project assignments for this staff member." onclick="assignStaff('${esc(s.id)}')">Assignments (${as.length})</button><button class="secondary" title="Edit the staff member's details, labour level and badge information." onclick="editStaff('${esc(s.id)}')">Edit</button></div>`
  }).join('')||'<p class=muted>No staff yet.</p>';
  layout('Staff & Assignments',`<div class="card"><div class="bar"><div><span class="eyebrow">RESOURCE PLANNER</span><h2>Project workforce</h2></div><button title="Add a new person to the master staff register." onclick="newStaff()">+ Add staff</button><button class="secondary" title="Restore the supplied standard staff register without deleting your own staff." onclick="restoreStandardStaff()">Restore standard staff</button></div><p class="muted">Staff levels and badge markers are based on the supplied labour-board images. Project assignments still use the established labour roles.</p>${rows}</div><div class="card"><div class="section-head"><div><span class="eyebrow">TRAINING REGISTER</span><h2>Training & competency records</h2><p class="muted">Store completed training, provider, completion/expiry dates, certificate references and notes against each staff member.</p></div></div><p class="muted">Use the <b>Training</b> button beside a person to add or maintain their records. Expiry dates are stored with the record so they can be reviewed before site deployment.</p></div>`,'staff')
 }catch(e){alert(e.message)}
}
async function trainingStaff(staffId){
 const s=window._staffCache?.find(x=>x.id===staffId); if(!s){alert('Staff member not found');return}
 try{
  const d=await api('/api/staff/'+encodeURIComponent(staffId)+'/training');
  const training=await Promise.all((d.training||[]).map(async x=>{try{const r=await api('/api/staff/'+encodeURIComponent(staffId)+'/training/'+encodeURIComponent(x.id)+'/documents');return {...x,documents:r.documents||[]}}catch(_){return {...x,documents:[]}}}));
  const rows=training.map(x=>`<div class="row"><div style="flex:1"><b>${esc(x.training_name)}</b><div class="muted">${esc(x.provider||'Provider not recorded')} • Completed ${esc(x.completed_date)}${x.expiry_date?' • Expires '+esc(x.expiry_date):' • No expiry recorded'} • ${esc(x.status)}</div>${x.certificate_ref?`<div class="muted">Certificate: ${esc(x.certificate_ref)}</div>`:''}${x.notes?`<div class="muted">${esc(x.notes)}</div>`:''}<div class="training-docs">${x.documents.length?x.documents.map(doc=>`<span class="training-doc"><a href="/api/staff-training-documents/${esc(doc.id)}" target="_blank">${esc(doc.filename)}</a><button class="secondary" data-help="Delete this uploaded training document." onclick="deleteTrainingDocument('${esc(staffId)}','${esc(x.id)}','${esc(doc.id)}')">Delete</button></span>`).join(''):'<span class="muted">No certificate/document uploaded.</span>'}</div></div><div class="task-actions"><button class="secondary" data-help="Upload a certificate or supporting document for this training record." onclick="chooseTrainingDocument('${esc(staffId)}','${esc(x.id)}')">Upload document</button><button class="secondary" data-help="Edit this training record." onclick="editTraining('${esc(staffId)}','${esc(x.id)}')">Edit</button><button class="secondary" data-help="Delete this training record." onclick="deleteTraining('${esc(staffId)}','${esc(x.id)}')">Delete</button></div></div>`).join('')||'<p class="muted">No training records stored for this person.</p>';
  modal('Training — '+esc(s.name),`${rows}<hr><h3>Add training record</h3><label>Training / course name</label><input id=tr_name placeholder="e.g. Manual Handling"><label>Provider</label><input id=tr_provider placeholder="Training provider"><label>Completed date</label><input id=tr_completed type=date><label>Expiry date (optional)</label><input id=tr_expiry type=date><label>Certificate / reference</label><input id=tr_cert placeholder="Certificate number or reference"><label>Status</label><select id=tr_status><option>Completed</option><option>Current</option><option>Expired</option><option>Pending</option></select><label>Notes</label><textarea id=tr_notes rows=3 placeholder="Additional details"></textarea><button title="Save this training record to the staff member's training history." onclick="saveTraining('${esc(staffId)}')">Save training record</button>`)
 }catch(e){alert(e.message)}
}
function chooseTrainingDocument(staffId,trainingId){const input=document.createElement('input');input.type='file';input.accept='.pdf,.doc,.docx,.xls,.xlsx,.jpg,.jpeg,.png,.txt';input.onchange=()=>{const f=input.files?.[0];if(f)uploadTrainingDocument(staffId,trainingId,f)};input.click()}
async function uploadTrainingDocument(staffId,trainingId,file){if(file.size>10*1024*1024){alert('Document is larger than 10 MB');return}const b64=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(String(r.result).split(',')[1]);r.onerror=rej;r.readAsDataURL(file)});try{await api('/api/staff/'+encodeURIComponent(staffId)+'/training/'+encodeURIComponent(trainingId)+'/documents',{method:'POST',body:JSON.stringify({filename:file.name,mime_type:file.type||'application/octet-stream',content_base64:b64})});trainingStaff(staffId)}catch(e){alert(e.message)}}
async function deleteTrainingDocument(staffId,trainingId,documentId){if(!confirm('Delete this uploaded training document?'))return;try{await api('/api/staff-training-documents/'+encodeURIComponent(documentId),{method:'DELETE'});trainingStaff(staffId)}catch(e){alert(e.message)}}
async function saveTraining(staffId){try{await api('/api/staff/'+encodeURIComponent(staffId)+'/training',{method:'POST',body:JSON.stringify({training_name:tr_name.value,provider:tr_provider.value,completed_date:tr_completed.value,expiry_date:tr_expiry.value,certificate_ref:tr_cert.value,status:tr_status.value,notes:tr_notes.value})});trainingStaff(staffId)}catch(e){alert(e.message)}}
async function editTraining(staffId,trainingId){try{const d=await api('/api/staff/'+encodeURIComponent(staffId)+'/training');const x=(d.training||[]).find(r=>r.id===trainingId);if(!x){alert('Training record not found');return}modal('Edit training record',`<label>Training / course name</label><input id=etr_name value="${esc(x.training_name)}"><label>Provider</label><input id=etr_provider value="${esc(x.provider||'')}"><label>Completed date</label><input id=etr_completed type=date value="${esc(x.completed_date)}"><label>Expiry date (optional)</label><input id=etr_expiry type=date value="${esc(x.expiry_date||'')}"><label>Certificate / reference</label><input id=etr_cert value="${esc(x.certificate_ref||'')}"><label>Status</label><select id=etr_status>${['Completed','Current','Expired','Pending'].map(v=>`<option ${v===x.status?'selected':''}>${v}</option>`).join('')}</select><label>Notes</label><textarea id=etr_notes rows=3>${esc(x.notes||'')}</textarea><button title="Save changes to this training record." onclick="updateTraining('${esc(staffId)}','${esc(trainingId)}')">Save changes</button>`)}catch(e){alert(e.message)}}
async function updateTraining(staffId,trainingId){try{await api('/api/staff/'+encodeURIComponent(staffId)+'/training/'+encodeURIComponent(trainingId),{method:'PUT',body:JSON.stringify({training_name:etr_name.value,provider:etr_provider.value,completed_date:etr_completed.value,expiry_date:etr_expiry.value,certificate_ref:etr_cert.value,status:etr_status.value,notes:etr_notes.value})});trainingStaff(staffId)}catch(e){alert(e.message)}}
async function deleteTraining(staffId,trainingId){if(!confirm('Delete this training record?'))return;try{await api('/api/staff/'+encodeURIComponent(staffId)+'/training/'+encodeURIComponent(trainingId),{method:'DELETE'});trainingStaff(staffId)}catch(e){alert(e.message)}}

async function assignStaff(staffId){const s=window._staffCache.find(x=>x.id===staffId);const a=await api('/api/project-assignments?staff_id='+encodeURIComponent(staffId));const rows=a.assignments.map(x=>`<div class="row"><div><b>${esc(x.project_name)}</b><div class="muted">${esc(x.assignment_role)} • ${esc(x.start_date)} → ${esc(x.finish_date||'open')} • ${esc(x.assignment_status)}</div></div><button class="secondary" onclick="editAssignment('${esc(x.id)}')">Edit</button><button class="secondary" onclick="finishAssignment('${esc(x.id)}')">${x.assignment_status==='Active'?'Finish':'Re-open'}</button></div>`).join('')||'<p class="muted">No project assignments yet.</p>';modal('Assignments — '+esc(s.name),`${rows}<hr><label>Project</label><select id=ap>${state.projects.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select><label>Assignment role</label><select id=ar>${ROLE_VALUES.map(r=>`<option ${r===s.position?'selected':''}>${esc(r)}</option>`).join('')}</select><label>Start date</label><input id=as type=date value="${new Date().toISOString().slice(0,10)}"><label>Finish date (optional)</label><input id=af type=date><label>Notes</label><input id=an placeholder="Area / package"><button onclick="saveAssignment('${esc(staffId)}')">Assign to project</button>`)}
async function editAssignment(id){const a=await api('/api/project-assignments?assignment_id='+encodeURIComponent(id));const x=a.assignments?.[0];if(!x){alert('Assignment not found');return}modal('Edit assignment',`<label>Project</label><input value="${esc(x.project_name)}" disabled><label>Assignment role</label><select id=e_ar>${ROLE_VALUES.map(r=>`<option ${r===x.assignment_role?'selected':''}>${esc(r)}</option>`).join('')}</select><label>Start date</label><input id=e_as type=date value="${esc(x.start_date)}"><label>Finish date</label><input id=e_af type=date value="${esc(x.finish_date||'')}"><label>Status</label><select id=e_ast><option ${x.assignment_status==='Active'?'selected':''}>Active</option><option ${x.assignment_status==='Held'?'selected':''}>Held</option><option ${x.assignment_status==='Finished'?'selected':''}>Finished</option></select><label>Notes</label><input id=e_an value="${esc(x.notes||'')}"><button onclick="updateAssignment('${esc(id)}')">Save assignment</button>`)}
async function updateAssignment(id){try{await api('/api/project-assignments/'+id,{method:'PUT',body:JSON.stringify({assignment_role:e_ar.value,start_date:e_as.value,finish_date:e_af.value,assignment_status:e_ast.value,notes:e_an.value})});closeModal();staffPage()}catch(e){alert(e.message)}}
async function finishAssignment(id){try{const a=await api('/api/project-assignments?assignment_id='+encodeURIComponent(id));const x=a.assignments?.[0];if(!x)return;await api('/api/project-assignments/'+id,{method:'PUT',body:JSON.stringify({assignment_status:x.assignment_status==='Active'?'Finished':'Active',finish_date:x.assignment_status==='Active'?new Date().toISOString().slice(0,10):x.finish_date,notes:x.notes||''})});closeModal();staffPage()}catch(e){alert(e.message)}}
async function saveAssignment(staffId){try{await api('/api/project-assignments',{method:'POST',body:JSON.stringify({staff_id:staffId,project_id:ap.value,assignment_role:ar.value,start_date:as.value,finish_date:af.value,notes:an.value})});document.querySelector('.modal')?.remove();staffPage()}catch(e){alert(e.message)}}
async function closeOut(){
 if(!state.projects.length){layout('End-of-Day Close Out','<div class="card"><h2>No projects available</h2></div>','closeout');return}
 if(!state.projectId) state.projectId=state.projects[0].id;
 const day=new Date().toISOString().slice(0,10);
 try{const d=await api('/api/daily-site-control?project_id='+encodeURIComponent(state.projectId)+'&date='+day);
  const action=d.tasks.filter(t=>t.status==='Held Up'||(t.finish_date<day&&t.status!=='Finished'));
  const finished=d.tasks.filter(t=>t.status==='Finished');
  layout('End-of-Day Close Out',`<div class="daily-head"><div><span class="eyebrow">10-MINUTE CLOSE OUT</span><h2>${esc(d.project.name)} — ${esc(day)}</h2><p class="muted">Confirm final status, leave tomorrow’s actions clear, then save.</p></div><select onchange="state.projectId=this.value;closeOut()">${state.projects.map(x=>`<option value="${esc(x.id)}" ${x.id===state.projectId?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="daily-kpis"><div><span>Finished</span><b>${finished.length}</b></div><div><span>Held up / overdue</span><b>${action.length}</b></div><div><span>On site</span><b>${d.actual_men}</b></div><div><span>Planned</span><b>${Number(d.planned_men).toFixed(1)}</b></div></div><div class="card"><h2>Outstanding work</h2>${action.map(t=>`<div class="row"><div><b>${esc(t.name)}</b><div class="muted">${esc(t.status)}${t.held_up_reason?' • '+esc(t.held_up_reason):''} • ${t.percent_complete}%</div></div></div>`).join('')||'<p class="muted">No held-up or overdue work.</p>'}</div><div class="card"><h2>Close-out notes</h2><label>Completed today<textarea id="coCompleted" rows="3">${esc(d.daily.completed_activities||'')}</textarea></label><label>Outstanding / action for tomorrow<textarea id="coDelays" rows="3">${esc(d.daily.delays||'')}</textarea></label><label>Close-out note<textarea id="coNotes" rows="3">${esc(d.daily.notes||'')}</textarea></label><button onclick="saveCloseOut('${esc(d.project.id)}','${esc(day)}')">✓ Save close out</button></div>`,'closeout');
 }catch(e){alert(e.message)}
}
async function saveCloseOut(pid,day){try{await api('/api/daily-site-control',{method:'POST',body:JSON.stringify({project_id:pid,date:day,attendance:[],tasks:[],status:'Complete',completed_activities:coCompleted.value,delays:coDelays.value,notes:coNotes.value,safety_check:'Not recorded'})});alert('Close out saved.');closeOut()}catch(e){alert(e.message)}}
async function restoreStandardStaff(){if(!confirm('Restore the standard staff register? Existing staff will be kept.'))return;try{await api('/api/staff/restore-standard',{method:'POST'});await staffPage()}catch(e){alert(e.message)}}
function newStaff(){modal('Add staff',`<label>Staff reference</label><input id=sr placeholder="EMP-001 (optional)"><label>Name</label><input id=sn><label>Labour level</label><select id=sl>${STAFF_LEVELS.map(x=>`<option>${esc(x)}</option>`).join('')}</select><label>Assignment position</label><select id=sp>${ROLE_VALUES.map(x=>`<option>${esc(x)}</option>`).join('')}</select><label>Badge</label><select id=sb><option value="">None</option><option>AWS Badge</option><option>Airport Badge</option><option>Airport Badge + AWS Badge</option></select><label>Site / source group</label><input id=sg placeholder="e.g. AWS Clon (E2882)"><button onclick="saveStaff()">Create staff member</button>`)}
async function saveStaff(){try{await api('/api/staff',{method:'POST',body:JSON.stringify({staff_ref:sr.value,name:sn.value,position:sp.value,labour_level:sl.value,badge_type:sb.value,source_group:sg.value,display_color:STAFF_LEVEL_COLORS[sl.value]||'',active:true})});closeModal();staffPage()}catch(e){alert(e.message)}}
function editStaff(id){const s=window._staffCache?.find(x=>x.id===id); if(!s){api('/api/staff?active=all').then(d=>{window._staffCache=d.staff;editStaff(id)});return} modal('Edit staff',`<label>Staff reference</label><input id=sr value="${esc(s.staff_ref)}"><label>Name</label><input id=sn value="${esc(s.name)}"><label>Labour level</label><select id=sl>${STAFF_LEVELS.map(x=>`<option ${x===(s.labour_level||'Unspecified')?'selected':''}>${esc(x)}</option>`).join('')}</select><label>Assignment position</label><select id=sp>${ROLE_VALUES.map(x=>`<option ${x===s.position?'selected':''}>${esc(x)}</option>`).join('')}</select><label>Badge</label><select id=sb><option value="" ${!s.badge_type?'selected':''}>None</option><option ${s.badge_type==='AWS Badge'?'selected':''}>AWS Badge</option><option ${s.badge_type==='Airport Badge'?'selected':''}>Airport Badge</option><option ${s.badge_type==='Airport Badge + AWS Badge'?'selected':''}>Airport Badge + AWS Badge</option></select><label>Site / source group</label><input id=sg value="${esc(s.source_group||'')}"><label>Active</label><select id=sa><option value="1" ${s.active?'selected':''}>Active</option><option value="0" ${!s.active?'selected':''}>Inactive</option></select><button onclick="updateStaff('${esc(id)}')">Save</button>`)}
async function updateStaff(id){try{await api('/api/staff/'+id,{method:'PUT',body:JSON.stringify({staff_ref:sr.value,name:sn.value,position:sp.value,labour_level:sl.value,badge_type:sb.value,source_group:sg.value,display_color:STAFF_LEVEL_COLORS[sl.value]||'',active:sa.value==='1'})});closeModal();staffPage()}catch(e){alert(e.message)}}

async function createDailyIssue(pid,day){
 const type=document.getElementById('qiType')?.value, title=document.getElementById('qiTitle')?.value.trim(), description=document.getElementById('qiDescription')?.value.trim();
 if(!title||!description){alert('Enter a title and brief description.');return}
 try{await api('/api/daily-site-issue',{method:'POST',body:JSON.stringify({project_id:pid,date:day,module:type,title,description})});document.getElementById('qiTitle').value='';document.getElementById('qiDescription').value='';alert(type+' added.');await dailySiteControl()}catch(e){alert(e.message)}
}
async function uploadDailyPhoto(pid,recordId,file){
 if(file.size>10*1024*1024) throw new Error('Photo must be 10 MB or smaller.');
 const reader=new FileReader();
 const b64=await new Promise((resolve,reject)=>{reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});
 await api('/api/attachments',{method:'POST',body:JSON.stringify({project_id:pid,record_id:recordId,filename:file.name,mime_type:file.type||'image/jpeg',content_base64:b64})});
}
